## Usage

```tsx lines=1,9-20
import { animated, useSpring, useIsomorphicLayoutEffect } from '@react-spring/web'

const MyComponent = ({position}) => {
    const [springs, api] = useSpring(() => {
        y: 0,
        x: 0,
    }, [])

