function App() {
  return (
    <div>
      <h1>我的应用</h1>
      <Suspense fallback={<div>加载中...</div>}>
        <HeavyComponent />
      </Suspense>
    </div>
  );
}
```

**Vue中的实现**：

```javascript
// 路由配置中使用懒加载
const routes = [
  {
    path: '/user',
    component: () => import('./views/User.vue') // 动态导入
  }
]
```

### 路由懒加载最佳实践

对于单页应用(SPA)，路由懒加载是提升初始加载速度的关键：

1. **按页面拆分代码**：每个路由对应一个独立的代码块
2. **按功能模块拆分**：相关功能打包在一起，避免过度分割
3. **预加载相关路由**：当用户很可能访问某个路由时，提前加载

```javascript
// Next.js中的路由预加载
import Link from 'next/link'
import { useRouter } from 'next/router'

export default function Home() {
  const router = useRouter()

  // 用户悬停在链接上时预加载页面
  const handleMouseEnter = () => {
    router.prefetch('/dashboard')
  }

module.exports = {
  // webpack配置
  plugins: [
    new ImageMinimizerPlugin({
      minimizer: {
        implementation: ImageMinimizerPlugin.imageminMinify,
        options: {
          plugins: [
            ['gifsicle', { interlaced: true }],
            ['jpegtran', { progressive: true }],
            ['optipng', { optimizationLevel: 5 }],
            ['svgo', { plugins: [{ removeViewBox: false }] }],
          ],
        },
      },
    }),
  ],
};
```

### 响应式图片加载

针对不同设备提供不同尺寸的图片，避免小屏幕设备下载大尺寸图片：

```html
<img
  srcset="small.jpg 480w, medium.jpg 768w, large.jpg 1200w"
  sizes="(max-width: 480px) 100vw, (max-width: 768px) 80vw, 1200px"
  src="fallback.jpg"
  alt="响应式图片"
>
```

- `srcset`：定义可用的图片源和它们的宽度
- `sizes`：定义在不同媒体条件下图片的显示宽度
- `src`：不支持srcset的浏览器的后备方案

## 预加载技术：抢占先机

### preload关键资源加载

`preload`告诉浏览器尽早加载关键资源，即使这些资源在页面中出现较晚：

```html

<link rel="preload" href="critical.css" as="style">

<link rel="preload" href="font.woff2" as="font" type="font/woff2" crossorigin>

开启HTTP/2只需在服务器端配置，客户端无需修改代码。但为了充分利用HTTP/2，应该：
- 避免文件合并（HTTP/1.1的优化方式）
- 避免使用域名分片（HTTP/1.1的优化方式）
- 确保使用HTTPS（HTTP/2要求加密）

### HTTP/3与QUIC协议

HTTP/3基于QUIC协议，使用UDP而非TCP，提供更快的连接建立和更好的弱网环境表现。

主要优势：
- 0-RTT连接建立
- 改进的拥塞控制
- 连接迁移支持（如从WiFi切换到4G）

### 资源压缩与Brotli

启用Gzip和Brotli压缩可以显著减少传输大小：

- **Gzip**：广泛支持，压缩率好
- **Brotli**：谷歌开发的更高效压缩算法，比Gzip节省15-25%带宽

服务器配置示例（Nginx）：

```nginx
# 开启Gzip
gzip on;
gzip_types text/plain text/css application/javascript application/json;

# 开启Brotli（需要ngx_brotli模块）
brotli on;
brotli_types text/plain text/css application/javascript application/json;
```

### 流式传输应用

对于大型响应，使用流式传输可以提高用户体验：

```javascript
// 服务端流式传输示例（Node.js）
app.get('/large-data', (req, res) => {
  const data = getVeryLargeData();

  // 设置响应头
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Transfer-Encoding', 'chunked');

  // 分块发送数据
  for (const chunk of data) {
    res.write(JSON.stringify(chunk) + '\n');
  }

  res.end();
});

// 客户端读取流式数据
fetch('/large-data')
  .then(response => {
    const reader = response.body.getReader();
    const decoder = new TextDecoder();

    function processChunk({ done, value }) {
      if (done) return;

      // 处理数据块
      const chunk = decoder.decode(value);
      console.log(chunk);

      // 继续读取下一块
      return reader.read().then(processChunk);
    }

    return reader.read().then(processChunk);
  });
```

## 文件优化：精简代码体积

### JavaScript压缩与混淆

减小JavaScript文件体积的方法：

1. **压缩（Minification）**：移除空格、注释和不必要的字符
2. **混淆（Obfuscation）**：重命名变量为更短的名称
3. **摇树优化（Tree Shaking）**：移除未使用的代码

常用工具：
- Terser：现代JavaScript压缩工具
- UglifyJS：经典的JavaScript压缩工具
- Webpack + TerserPlugin：在构建流程中集成

```javascript
// webpack配置示例
module.exports = {
  optimization: {
    minimize: true,
    minimizer: [
      new TerserPlugin({
        terserOptions: {
          compress: {
            drop_console: true, // 删除console语句
          },
          mangle: true, // 变量名混淆
        },
      }),
    ],
  },
};
```

#### First Contentful Paint (FCP)：首次内容绘制

**简单理解**：用户看到页面上首个内容（文本、图片等）的时间点。

```javascript
// 通过Performance API获取FCP
new PerformanceObserver((entryList) => {
  for (const entry of entryList.getEntries()) {
    console.log('FCP:', entry.startTime);
  }
}).observe({type: 'paint', buffered: true});
```

**优化方向**：减小初始HTML大小、内联关键CSS、移除渲染阻塞资源。

**健康标准**：
- 良好：0-1.8秒
- 需要改进：1.8-3秒
- 较差：3秒以上

#### Largest Contentful Paint (LCP)：最大内容绘制

**简单理解**：页面主要内容加载完成的时间点，通常是最大的图片、视频或文本块的呈现时间。

```javascript
// 通过Performance API获取LCP
new PerformanceObserver((entryList) => {
  const entries = entryList.getEntries();
  const lastEntry = entries[entries.length - 1]; // 取最后一次测量
  console.log('LCP:', lastEntry.startTime);
}).observe({type: 'largest-contentful-paint', buffered: true});
```

**为什么LCP比FCP更重要**？因为它代表了用户感知的页面主要内容加载完成的时间，更接近用户的真实体验。

**优化方向**：优化服务器响应时间、减少资源加载时间、使用图片懒加载等。

#### First Input Delay (FID)：首次输入延迟

**简单理解**：用户首次与页面交互（如点击按钮）到浏览器能够响应的延迟时间。

```javascript
// 通过Performance API获取FID
new PerformanceObserver((entryList) => {
  for (const entry of entryList.getEntries()) {
    console.log('FID:', entry.processingStart - entry.startTime);
  }
}).observe({type: 'first-input', buffered: true});
```

想象你点击一个按钮，但要等待半秒才有反应，这种延迟会让用户感到不适。

**优化方向**：拆分长任务、优化事件处理函数、减少主线程工作量。

#### Cumulative Layout Shift (CLS)：累积布局偏移

**简单理解**：页面元素在加载过程中意外移动的程度，数值越低越好。

```javascript
// 通过Performance API获取CLS
let cls = 0;
new PerformanceObserver((entryList) => {
  for (const entry of entryList.getEntries()) {
    if (!entry.hadRecentInput) {
      cls += entry.value;
    }
  }
  console.log('CLS:', cls);
}).observe({type: 'layout-shift', buffered: true});
```

**常见原因**：
- 无尺寸的图片和视频
- 字体文件导致的闪烁
- 动态插入的内容
- 尺寸未知的广告位

**优化方向**：为图片和视频元素指定尺寸、使用字体显示策略、保留足够的空间给动态内容。

#### Performance API

现代浏览器提供了Performance API，让开发者可以通过代码获取性能数据。

```javascript
// 测量代码执行时间
const startTime = performance.now();
// 执行某些操作
doSomething();
const endTime = performance.now();
console.log(`操作耗时: ${endTime - startTime}毫秒`);

// 获取导航相关的性能数据
const navData = performance.getEntriesByType('navigation')[0];
console.log(`页面加载总时间: ${navData.loadEventEnd - navData.startTime}毫秒`);
```

#### User Timing API

可以在代码中添加自定义的性能标记点，测量特定操作的耗时。

```javascript
// 开始标记
performance.mark('数据处理-开始');

// 处理数据
processData();

// 结束标记
performance.mark('数据处理-结束');

// 创建测量
performance.measure('数据处理耗时', '数据处理-开始', '数据处理-结束');

// 获取测量结果
const measures = performance.getEntriesByName('数据处理耗时');
console.log(`数据处理耗时: ${measures[0].duration}毫秒`);
```

### 3. 真实用户监控 (RUM)

实验室测试无法完全模拟真实用户环境，因此需要收集真实用户的性能数据。

**实现方式**：
1. 通过Performance API收集性能数据
2. 发送到分析服务器
3. 聚合分析数据，发现问题

```javascript
// 简单的RUM实现示例
window.addEventListener('load', () => {
  // 等待页面稳定
  setTimeout(() => {
    const navigation = performance.getEntriesByType('navigation')[0];
    const paint = performance.getEntriesByType('paint');

    // 收集关键性能指标
    const metrics = {
      url: document.URL,
      deviceType: getDeviceType(),
      connection: navigator.connection?.effectiveType || 'unknown',
      loadTime: navigation.loadEventEnd - navigation.startTime,
      fcp: paint.find(entry => entry.name === 'first-contentful-paint')?.startTime
    };

    // 发送到服务器
    navigator.sendBeacon('/analytics', JSON.stringify(metrics));
  }, 0);
});
```

