```

2. **使用`useMemo`和`useCallback`缓存计算结果和回调函数**

```jsx
function SearchResults({ query, data }) {
  // 缓存过滤结果，query或data变化时才重新计算
  const filteredData = useMemo(() => {
    return data.filter(item => item.name.includes(query));
  }, [query, data]);

  // 缓存回调函数，避免每次渲染创建新函数
  const handleClick = useCallback((id) => {
    console.log('Clicked item:', id);
  }, []);

  return (
    <ul>
      {filteredData.map(item => (
        <li key={item.id} onClick={() => handleClick(item.id)}>
          {item.name}
        </li>
      ))}
    </ul>
  );
}
```

3. **合理使用`key`属性**：在列表渲染中，提供稳定的key值帮助React识别元素变化

```jsx
// 好的做法：使用唯一ID作为key
<ul>
  {users.map(user => <li key={user.id}>{user.name}</li>)}
</ul>

// 不好的做法：使用索引作为key
<ul>
  {users.map((user, index) => <li key={index}>{user.name}</li>)}
</ul>
```

### 虚拟DOM与Diff算法

虚拟DOM是一种轻量级的JavaScript对象，用于表示真实DOM结构。当数据变化时，框架会创建新的虚拟DOM树，与旧树进行比较(Diff)，计算出最小的DOM操作。

Diff算法优化原则：
1. 只比较同级元素，不跨级比较
2. 不同类型的元素直接替换，不深入比较
3. 使用key属性帮助识别元素变化

```jsx
// React中的key属性帮助优化Diff过程
function TodoList({ todos }) {
  return (
    <ul>
      {todos.map(todo => (
        // 使用稳定的ID作为key
        <li key={todo.id}>
          {todo.text}
        </li>
      ))}
    </ul>
  );
}
```

### 时间分片与并发渲染

为了避免长时间运行的JavaScript阻塞主线程，可以使用时间分片技术：

```javascript
// 使用requestIdleCallback分片处理大量数据
function processData(data, callback) {
  // 每次处理的数据量
  const CHUNK_SIZE = 100;
  // 数据总长度
  const length = data.length;
  // 已处理的索引
  let index = 0;

  function process() {
    // 获取当前时间点
    const startTime = Date.now();

    // 处理当前批次数据
    while (index < length && Date.now() - startTime < 16) {
      // 处理单个数据项
      const item = data[index++];
      // 进行实际处理...
    }

    // 如果还有未处理的数据，继续下一批次
    if (index < length) {
      requestIdleCallback(process);
    } else {
      // 全部完成后调用回调
      callback();
    }
  }

  // 开始处理
  requestIdleCallback(process);
}

// 使用时间分片更新DOM
processData(largeDataset, () => {
  console.log('All data processed');
});
```

React 18引入的并发特性基于类似原理，允许渲染工作被中断和恢复：

```jsx
// React 18的并发渲染示例
import { startTransition } from 'react';

function SearchComponent() {
  const [searchText, setSearchText] = useState('');
  const [searchResults, setSearchResults] = useState([]);

  function handleChange(e) {
    // 获取输入值立即更新，优先级高
    setSearchText(e.target.value);

    // 搜索结果更新标记为低优先级
    startTransition(() => {
      // 可能耗时的操作，可被中断
      const results = performExpensiveSearch(e.target.value);
      setSearchResults(results);
    });
  }

  return (
    <>
      <input value={searchText} onChange={handleChange} />
      <SearchResults results={searchResults} />
    </>
  );
}
```

```javascript
// 服务端设置Cookie (Node.js Express示例)
app.get('/login', (req, res) => {
  // 验证用户身份...
  res.cookie('sessionId', 'abc123', {
    maxAge: 86400000, // 24小时
    httpOnly: true,   // 防止JavaScript访问
    secure: true,     // 仅HTTPS
    sameSite: 'strict' // 防止CSRF
  });
  res.send('登录成功');
