```

### 并发控制：同时发起多个异步请求

async/await 并不意味着要串行执行所有异步操作，你可以结合 Promise.all 实现并发。

```javascript
async function getUsersAndProducts() {
  try {
    // 同时发起两个请求
    const [usersResponse, productsResponse] = await Promise.all([
      fetch('/api/users'),
      fetch('/api/products')
    ]);

    // 同时解析两个响应
    const [users, products] = await Promise.all([
      usersResponse.json(),
      productsResponse.json()
    ]);

    return { users, products };
  } catch (error) {
    console.log('出错了:', error);
    return { users: [], products: [] };
  }
}
```

### 最佳实践：让代码更健壮

1. **永远不要忘记错误处理**
```javascript
// 不好的实践
async function getData() {
  const response = await fetch('/api/data');
  const data = await response.json();
  return data;
}

// 好的实践
async function getData() {
  try {
    const response = await fetch('/api/data');
    if (!response.ok) {
      throw new Error(`HTTP错误! 状态码: ${response.status}`);
    }
    const data = await response.json();
    return data;
  } catch (error) {
    console.error('获取数据失败:', error);
    throw error; // 重新抛出或返回默认值
  }
}
```

2. **注意 async 函数总是返回 Promise**
```javascript
// 这看起来返回一个数字
async function getValue() {
  return 42;
}

// 实际上返回的是Promise
getValue().then(value => console.log(value)); // 输出 42
```

### 网络请求：前端最常见的异步场景

```javascript
// 封装一个通用的API请求函数
async function apiRequest(url, method = 'GET', data = null) {
  try {
    const options = {
      method,
      headers: {
        'Content-Type': 'application/json'
      }
    };

    if (data) {
      options.body = JSON.stringify(data);
    }

    const response = await fetch(url, options);

    if (!response.ok) {
      throw new Error(`请求失败: ${response.status}`);
    }

    return await response.json();
  } catch (error) {
    console.error('API请求错误:', error);
    throw error;
  }
}

// 使用示例
async function getUserProfile(userId) {
  try {
    const user = await apiRequest(`/api/users/${userId}`);
    const posts = await apiRequest(`/api/users/${userId}/posts`);
    return { user, posts };
  } catch (error) {
    console.log('获取用户资料失败');
    return null;
  }
}
```

