### setTimeout 与 clearTimeout

```javascript
// 延迟执行一次
let timeoutId = setTimeout(function() {
  console.log('3秒后执行一次');
}, 3000);

// 取消定时器
clearTimeout(timeoutId);

// 使用箭头函数和参数
setTimeout((name) => {
  console.log(`你好，${name}！`);
}, 1000, '小明');
```

`setTimeout`用于在指定的毫秒数后执行一次函数。它返回一个ID，可以用`clearTimeout`取消执行。

### setInterval 与 clearInterval

```javascript
// 重复执行
let count = 0;
let intervalId = setInterval(function() {
  console.log(`这是第${++count}次执行`);
  if (count >= 5) {
    clearInterval(intervalId); // 5次后停止
  }
}, 1000);

// 取消重复执行
clearInterval(intervalId);
```

`setInterval`用于按照固定的时间间隔重复执行函数，直到被`clearInterval`取消或窗口关闭。

### requestAnimationFrame

```javascript
// 基本用法
function animate() {
  // 更新动画
  element.style.left = (parseInt(element.style.left) || 0) + 1 + 'px';

  // 如果还需要继续动画，再次请求
  if (parseInt(element.style.left) < 300) {
    requestAnimationFrame(animate);
  }
}

// 开始动画
let animationId = requestAnimationFrame(animate);

// 取消动画
cancelAnimationFrame(animationId);
```

`requestAnimationFrame`是专为动画设计的定时方法，它会在浏览器下一次重绘之前调用指定函数。与`setTimeout`相比，它有以下优势：
- 浏览器会优化，使动画更平滑
- 在不可见的标签页中会暂停，节省CPU
- 会自动适应显示器的刷新率

### 语法错误

```javascript
// 语法错误示例
function greeting() {
  console.log("Hello world"   // 缺少闭合括号
}

if (x === 5   // 缺少闭合括号和分号
```

语法错误（SyntaxError）发生在代码解析阶段，通常是由于代码结构不符合JavaScript语法规则造成的。例如缺少括号、分号，或使用了未声明的变量等。这类错误会阻止整个脚本的执行，在开发环境中可以通过IDE或开发者工具立即发现。

### 逻辑错误

```javascript
// 逻辑错误示例
function calculateArea(radius) {
  return radius * radius;  // 错误算法：圆面积应该是 Math.PI * radius * radius
}

// 意外的类型转换
if (1 == "1") {  // 总是为true，应使用严格相等 ===
  console.log("相等");
}
```

逻辑错误是最难发现的错误类型，因为它们不会产生语法或运行时异常。程序会正常执行，但结果不符合预期。这类错误通常源于算法实现有误、变量使用错误或对语言特性理解不深入等。

### 自定义错误

```javascript
// 创建自定义错误类型
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = "ValidationError";
    this.code = "ERR_VALIDATION";
  }
}

// 使用自定义错误
function validateUser(user) {
  if (!user.name) {
    throw new ValidationError("用户名不能为空");
  }

  if (user.age < 18) {
    throw new ValidationError("用户必须年满18岁");
  }
}

try {
  validateUser({ name: "张三", age: 16 });
} catch (error) {
  if (error instanceof ValidationError) {
    console.log(`验证失败: ${error.message}`);
  } else {
    console.log("未知错误:", error);
  }
}
```

创建自定义错误类可以让错误处理更具语义化，便于识别和处理特定类型的业务逻辑错误。通过继承内置`Error`类，我们可以添加额外的属性和方法来提供更多上下文信息。

### try/catch

```javascript
// 基本用法
try {
  // 可能出错的代码
  const data = JSON.parse(invalidJsonString);
  console.log(data);
} catch (error) {
  // 错误处理
  console.error("解析JSON失败:", error.message);
} finally {
  // 无论是否出错都会执行
  console.log("处理完成");
}

// 根据错误类型处理
try {
  throw new TypeError("类型错误示例");
} catch (error) {
  if (error instanceof SyntaxError) {
    console.log("语法错误");
  } else if (error instanceof TypeError) {
    console.log("类型错误");
  } else {
    console.log("其他错误");
  }
}
```

`try/catch/finally`是最基本的错误处理机制，适用于同步代码。`try`块中的代码如果抛出异常，执行会立即跳转到`catch`块，之后无论是否有错误，`finally`块中的代码都会执行。

### Promise.catch

```javascript
// Promise错误处理
fetch('https://api.example.com/data')
  .then(response => {
    if (!response.ok) {
      throw new Error(`HTTP错误: ${response.status}`);
    }
    return response.json();
  })
  .then(data => {
    console.log("数据:", data);
  })
  .catch(error => {
    console.error("获取数据失败:", error.message);
  })
  .finally(() => {
    console.log("请求完成");
  });

// 链式Promise处理中的错误
Promise.resolve()
  .then(() => {
    throw new Error("步骤1出错");
    return "步骤1结果";
  })
  .then(result => {
    console.log(result);  // 不会执行
    return "步骤2结果";
  })
  .catch(error => {
    console.error(error.message);  // "步骤1出错"
    return "恢复正常";  // 返回值让链继续执行
  })
  .then(result => {
    console.log(result);  // "恢复正常"
  });
```

对于基于Promise的异步操作，使用`.catch()`方法可以捕获整个Promise链中的错误。Promise错误有"冒泡"特性，链中任何一环节抛出的错误都会被最近的`.catch()`捕获。

### async/await

```javascript
// async/await错误处理
async function fetchData() {
  try {
    const response = await fetch('https://api.example.com/data');
    if (!response.ok) {
      throw new Error(`HTTP错误: ${response.status}`);
    }
    const data = await response.json();
    return data;
  } catch (error) {
    console.error("获取数据失败:", error.message);
    // 可以返回默认值，或重新抛出错误
    return { error: true, message: error.message };
  } finally {
    console.log("异步操作完成");
  }
}

// 调用并处理结果
fetchData()
  .then(result => {
    if (result.error) {
      console.log("使用备用数据");
    } else {
      console.log("数据:", result);
    }
  });
```

使用`async/await`让异步错误处理变得更直观，可以像处理同步代码一样使用`try/catch`。这种方式提高了异步代码的可读性和可维护性。

### 全局捕获

```javascript
// 处理未捕获的Promise错误
window.addEventListener('unhandledrejection', event => {
  console.warn('未处理的Promise拒绝:', event.promise, event.reason);
  // 阻止默认处理（防止控制台输出错误信息）
  event.preventDefault();
});

// 处理未捕获的普通错误
window.onerror = function(message, source, lineno, colno, error) {
  console.error('全局错误:', {
    message,
    source,   // 脚本URL
    lineno,   // 行号
    colno,    // 列号
    error     // 错误对象
  });

  // 向服务器发送错误信息
  sendErrorToServer({
    type: 'uncaught',
    message,
    source,
    stack: error ? error.stack : null
  });

  // 返回true阻止浏览器默认错误处理
  return true;
};
```

全局错误处理机制是捕获那些漏网之鱼的最后防线。通过`window.onerror`和`unhandledrejection`事件，我们可以捕获未被本地try/catch块处理的错误，记录它们或向用户提供反馈。

### 错误日志

```javascript
// 基本错误日志
function logError(error, context = {}) {
  console.group('错误详情');
  console.error(error.message);
  console.error('错误类型:', error.name);
  console.error('错误栈:', error.stack);
  console.error('上下文:', context);
  console.groupEnd();
}

// 结构化日志
function structuredLogError(error, context = {}) {
  const errorInfo = {
    message: error.message,
    name: error.name,
    stack: error.stack,
    time: new Date().toISOString(),
    context,
    // 添加用户环境信息
    userAgent: navigator.userAgent,
    url: window.location.href
  };

  console.error(JSON.stringify(errorInfo, null, 2));

  // 也可以存储到本地或发送到服务器
}
```

良好的错误日志是排查问题的基础。除了错误本身的信息，添加上下文数据（如用户操作、应用状态）可以帮助我们更好地理解错误发生的原因。

### 错误上报

```javascript
// 向服务器发送错误报告
async function reportError(error, context = {}) {
  try {
    const errorData = {
      message: error.message,
      stack: error.stack,
      type: error.name,
      time: new Date().toISOString(),
      userAgent: navigator.userAgent,
      url: window.location.href,
      ...context
    };

    // 使用Beacon API在页面关闭时也能发送数据
    if (navigator.sendBeacon) {
      navigator.sendBeacon('/api/error-report', JSON.stringify(errorData));
      return;
    }

    // 备用方案：使用fetch API
    await fetch('/api/error-report', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(errorData),
      // 保证不阻塞页面操作
      keepalive: true
    });
  } catch (reportError) {
    // 防止上报过程本身出错
    console.error('错误上报失败:', reportError);
  }
}
```

错误上报系统可以帮助我们收集生产环境中的错误数据，了解应用的健康状况，及时发现并修复问题。现代应用通常会使用第三方服务（如Sentry、LogRocket等）来监控和分析错误。

### 错误恢复

```javascript
// 提供备用功能或数据
function fetchUserData(userId) {
  return fetch(`/api/users/${userId}`)
    .then(response => response.json())
    .catch(error => {
      console.error('获取用户数据失败:', error);
      // 返回缓存或默认数据
      return getCachedUserData(userId) || {
        id: userId,
        name: '未知用户',
        isDefaultData: true
      };
    });
}

// 自动重试机制
async function fetchWithRetry(url, options = {}, retries = 3, delay = 1000) {
  try {
    return await fetch(url, options);
  } catch (error) {
    if (retries <= 0) {
      throw error;
    }

    console.log(`请求失败，${delay}ms后重试，剩余重试次数: ${retries - 1}`);
    await new Promise(resolve => setTimeout(resolve, delay));
    return fetchWithRetry(url, options, retries - 1, delay * 2);
  }
}
```

错误恢复机制帮助应用在出现错误后继续工作。常见策略包括提供默认值、使用本地缓存数据、自动重试操作或提供替代功能。良好的恢复机制可以显著提升用户体验。

### 降级处理

```javascript
// 功能降级示例
function renderUserDashboard(userData) {
  try {
    // 尝试使用完整功能
    renderComplexDashboard(userData);
  } catch (error) {
    console.warn('高级仪表盘渲染失败，降级到简单版本:', error);
    try {
      // 降级到简单版本
      renderSimpleDashboard(userData);
    } catch (fallbackError) {
      // 再次降级到最基本版本
      console.error('简单仪表盘也失败了:', fallbackError);
      renderBasicUserInfo(userData);
    }
  }
}

// 特性检测与降级
function setupApplication() {
  let storageSystem;

  try {
    // 尝试使用IndexedDB
    if ('indexedDB' in window) {
      storageSystem = new IndexedDBStorage();
    } else if ('localStorage' in window) {
      // 降级到localStorage
      storageSystem = new LocalStorageAdapter();
    } else {
      // 最终降级到内存存储
      storageSystem = new InMemoryStorage();
    }
  } catch (error) {
    console.error('存储系统初始化失败:', error);
    storageSystem = new InMemoryStorage();
  }

  return { storageSystem };
}
```

降级处理策略允许应用根据环境和错误情况动态调整其功能集。通过提供多级备选方案，即使在部分系统失效的情况下，应用仍能提供核心功能，保持可用性。

### 错误预防

```javascript
// 输入验证
function calculateDiscount(price, discountPercent) {
  // 类型检查
  if (typeof price !== 'number' || typeof discountPercent !== 'number') {
    throw new TypeError('价格和折扣必须是数字');
  }

  // 范围检查
  if (price < 0) {
    throw new RangeError('价格不能为负数');
  }

  if (discountPercent < 0 || discountPercent > 100) {
    throw new RangeError('折扣必须在0-100之间');
  }

  return price * (1 - discountPercent / 100);
}

// 防御性编程 - 空值处理
function getUserName(user) {
  // 使用可选链操作符
  const name = user?.name || '未知用户';
  return name;
}

// 安全地访问对象属性
const data = response?.data?.items?.[0]?.title || '默认标题';

// 类型保护（TypeScript）
function processValue(value: unknown): string {
  if (typeof value === 'string') {
    return value.toUpperCase();
  } else if (typeof value === 'number') {
    return value.toString();
  }
  return String(value);
}
```

"预防胜于治疗"同样适用于编程。通过输入验证、类型检查、默认值和防御性编程，我们可以减少错误发生的可能性。ES2020引入的可选链（`?.`）和空值合并（`??`）操作符为处理潜在的空值提供了简洁的语法。

