// 错误栈增强
function enhanceError(error, context) {
  // 保留原始栈
  const originalStack = error.stack;

  // 添加自定义信息
  error.additionalInfo = context;

// 可以添加自定义格式化方法
  error.prettyPrint = function() {
    console.error(`错误: ${this.message}`);
    console.error(`上下文: ${JSON.stringify(this.additionalInfo, null, 2)}`);
    console.error(`栈: ${originalStack}`);
  };

  return error;
}
```

当错误发生时，快速定位问题的根源是关键。良好的错误消息应该包含足够的上下文信息，清晰指出错误的位置和可能的原因。记录操作的中间状态、增强错误栈信息和添加环境细节都有助于加速调试过程。

### 错误监控

```javascript
// 简单的错误监控系统
class ErrorMonitor {
  constructor(options = {}) {
    this.options = {
      sampleRate: 1.0,  // 采样率，1.0表示100%
      maxErrors: 10,     // 每会话最大上报错误数
      ...options
    };

    this.errorCount = 0;
    this.setup();
  }

  setup() {
    // 捕获未处理的Promise错误
    window.addEventListener('unhandledrejection', event => {
      this.captureError(event.reason, { type: 'unhandledPromise' });
    });

    // 捕获普通JS错误
    window.onerror = (message, source, lineno, colno, error) => {
      this.captureError(error || { message }, { type: 'uncaught', source, lineno, colno });
      return false;  // 允许默认处理
    };

// 捕获网络错误
    window.addEventListener('error', event => {
      // 只处理资源加载错误
      if (event.target && (event.target.tagName === 'SCRIPT' ||
          event.target.tagName === 'LINK' ||
          event.target.tagName === 'IMG')) {
        this.captureError(new Error(`资源加载失败: ${event.target.src || event.target.href}`),
          { type: 'resource', element: event.target.tagName });
      }
    }, true);  // 使用捕获阶段以确保捕获
  }

  shouldReport() {
    // 采样逻辑
    if (Math.random() > this.options.sampleRate) {
      return false;
    }

    // 频率限制
    if (this.errorCount >= this.options.maxErrors) {
      return false;
    }

    this.errorCount++;
    return true;
  }

  captureError(error, context = {}) {
    if (!this.shouldReport()) {
      return;
    }

const errorData = {
      message: error.message || String(error),
      stack: error.stack,
      timestamp: new Date().toISOString(),
      url: window.location.href,
      userAgent: navigator.userAgent,
      ...context
    };

    // 异步发送，不阻塞主线程
    setTimeout(() => {
      this.sendError(errorData);
    }, 0);
  }

  sendError(errorData) {
    // 实际应用中，这里会发送到服务器
    console.log('向服务器发送错误:', errorData);

    // 使用Beacon API或fetch发送数据
    // navigator.sendBeacon('/api/errors', JSON.stringify(errorData));
  }
}

// 使用监控系统
const monitor = new ErrorMonitor({
  sampleRate: 0.5,  // 只上报50%的错误
  maxErrors: 5      // 每会话最多上报5个错误
});

// 手动上报错误
try {
  riskyOperation();
} catch (error) {
  monitor.captureError(error, {
    component: 'PaymentProcessor',
    operation: 'processPayment'
  });
}
```

错误监控系统帮助我们持续跟踪应用的健康状态，了解用户在实际使用中遇到的问题。通过收集和分析错误数据，我们可以识别最常见的问题、了解影响范围并优先修复重要的BUG。现代前端应用通常会集成专门的错误监控服务。

### 性能优化

```javascript
// 避免过度使用try/catch
function processLargeArray(items) {
  // 不好的做法: 在循环内部使用try/catch
  // for (const item of items) {
  //   try {
  //     processItem(item);
  //   } catch (error) {
  //     console.error('处理项目失败:', item, error);
  //   }
  // }

  // 更好的做法: 将try/catch移到外部
  try {
    for (const item of items) {
      processItem(item);
    }
  } catch (error) {
    console.error('处理数组项目失败:', error);
    // 可以重新抛出或返回部分结果
  }
}

// 错误处理与性能的平衡
function findUserByEmail(users, email) {
  // 验证输入
  if (!email || typeof email !== 'string') {
    return null;  // 无效输入时返回null，而不是抛出异常
  }

  return users.find(user => user.email === email) || null;
}

// 批量处理错误
function processBatch(items) {
  const results = [];
  const errors = [];

  for (const item of items) {
    try {
      results.push(processItem(item));
    } catch (error) {
      // 记录错误但继续处理其他项
      errors.push({ item, error });
    }
  }

  // 批量返回结果和错误
  return { results, errors };
}
```

错误处理虽然重要，但也需要考虑性能影响。`try/catch`块会影响JavaScript引擎的优化，过度使用可能导致性能下降。对于非关键操作或高频调用的代码，可以考虑使用返回特殊值（如`null`或错误对象）而非抛出异常。在处理大量数据时，可以采用批量错误处理策略，减少单个错误对整体流程的影响。

### 事件类型：各种各样的交互信号

JavaScript 中有多种类型的事件，它们就像不同类型的感官，让网页能够感知不同的用户交互：

```javascript
// 常见的事件类型示例
document.getElementById('myButton').addEventListener('click', function() {
  console.log('按钮被点击了');
});

document.getElementById('myInput').addEventListener('keydown', function() {
  console.log('键盘按下了');
});

document.getElementById('myDiv').addEventListener('mouseover', function() {
  console.log('鼠标移入了');
});
```

常见的事件类型包括：
- **鼠标事件**：click（点击）、dblclick（双击）、mouseover（鼠标移入）等
- **键盘事件**：keydown（键盘按下）、keyup（键盘释放）等
- **表单事件**：submit（表单提交）、change（表单元素值变化）等
- **窗口事件**：load（页面加载完成）、resize（窗口大小改变）等

### 事件对象：事件的信息载体

当事件发生时，浏览器会创建一个事件对象（event object），它包含了与事件相关的各种信息，就像是事件的"身份证"。

```javascript
document.getElementById('myButton').addEventListener('click', function(event) {
  // event就是事件对象
  console.log('事件类型:', event.type); // 输出: "click"
  console.log('事件目标:', event.target); // 输出: 被点击的元素
  console.log('点击坐标:', event.clientX, event.clientY); // 输出: 鼠标点击的坐标

  // 阻止默认行为
  event.preventDefault();
});
```

事件对象的常用属性和方法：
- `event.type`：事件类型（如 "click"、"keydown" 等）
- `event.target`：触发事件的元素
- `event.currentTarget`：绑定事件处理程序的元素
- `event.preventDefault()`：阻止事件的默认行为
- `event.stopPropagation()`：阻止事件冒泡

### 事件处理：响应事件的方式

当事件发生时，我们需要有相应的代码来处理它，这就是"事件处理程序"（event handler）。有三种方式可以添加事件处理程序：

1. **HTML 行内属性**（不推荐）

```html
<button onclick="alert('按钮被点击了')">点击我</button>
```

2. **DOM 属性**

```javascript
// 获取元素
const button = document.getElementById('myButton');

// 添加事件处理程序
button.onclick = function() {
  alert('按钮被点击了');
};

// 注意：这种方式一个事件只能绑定一个处理程序
button.onclick = function() {
  alert('这会覆盖之前的处理程序');
};
```

3. **addEventListener 方法**（推荐）

```javascript
// 获取元素
const button = document.getElementById('myButton');

// 添加事件处理程序
button.addEventListener('click', function() {
  alert('按钮被点击了 - 处理程序1');
});

// 可以添加多个处理程序
button.addEventListener('click', function() {
  alert('按钮被点击了 - 处理程序2');
});
```

### 事件绑定：为什么推荐 addEventListener？

`addEventListener` 是添加事件监听器的最佳方式，因为它：

1. 允许为同一事件添加多个处理程序
2. 提供了更精细的控制，如事件捕获阶段的处理
3. 可以简单地移除事件监听器

```javascript
function handleClick() {
  console.log('按钮被点击了');
}

// 添加事件监听器
button.addEventListener('click', handleClick);

// 移除事件监听器
button.removeEventListener('click', handleClick);
```

### 事件冒泡：从内到外的传播

事件冒泡是指事件最开始由最具体的元素（文档中嵌套层次最深的那个节点）接收，然后逐级向上传播到较为不具体的节点。就像水中的气泡从水底向水面升起。

```html
<div id="outer">
  <div id="inner">
    <button id="button">点击我</button>
  </div>
</div>
```

```javascript
// 为所有元素添加点击事件
document.getElementById('button').addEventListener('click', function() {
  console.log('按钮被点击了');
});

document.getElementById('inner').addEventListener('click', function() {
  console.log('内层div被点击了');
});

document.getElementById('outer').addEventListener('click', function() {
  console.log('外层div被点击了');
});

// 当点击按钮时，控制台输出顺序:
// "按钮被点击了"
// "内层div被点击了"
// "外层div被点击了"
```

### 事件捕获：从外到内的传播

事件捕获与冒泡相反，事件从最不具体的节点开始传播，然后逐级向下，直到最具体的节点。这就像是水滴落下，从高处向低处流动。

```javascript
// 为所有元素添加点击事件，启用捕获阶段
document.getElementById('outer').addEventListener('click', function() {
  console.log('外层div被点击了 (捕获)');
}, true); // 第三个参数true表示在捕获阶段触发

document.getElementById('inner').addEventListener('click', function() {
  console.log('内层div被点击了 (捕获)');
}, true);

document.getElementById('button').addEventListener('click', function() {
  console.log('按钮被点击了 (捕获)');
}, true);

// 当点击按钮时，控制台输出顺序:
// "外层div被点击了 (捕获)"
// "内层div被点击了 (捕获)"
// "按钮被点击了 (捕获)"
```

### 完整的事件流程

完整的事件流程包括三个阶段：
1. **捕获阶段**：事件从 window 对象自上而下向目标元素传播
2. **目标阶段**：事件到达目标元素
3. **冒泡阶段**：事件从目标元素自下而上向 window 对象传播

```javascript
// 一个完整的例子，同时监听捕获和冒泡阶段
function handleEvent(event) {
  console.log(`${event.currentTarget.id} 在 ${event.eventPhase === 1 ? '捕获' : '冒泡'} 阶段被触发`);
}

document.getElementById('outer').addEventListener('click', handleEvent, true); // 捕获
document.getElementById('inner').addEventListener('click', handleEvent, true); // 捕获
document.getElementById('button').addEventListener('click', handleEvent, true); // 捕获

document.getElementById('outer').addEventListener('click', handleEvent); // 冒泡
document.getElementById('inner').addEventListener('click', handleEvent); // 冒泡
document.getElementById('button').addEventListener('click', handleEvent); // 冒泡

// 当点击按钮时，控制台输出顺序:
// "outer 在 捕获 阶段被触发"
// "inner 在 捕获 阶段被触发"
// "button 在 捕获 阶段被触发"
// "button 在 冒泡 阶段被触发"
// "inner 在 冒泡 阶段被触发"
// "outer 在 冒泡 阶段被触发"
```

### 事件委托：利用冒泡实现高效事件处理

事件委托是一种利用事件冒泡的编程技巧，它允许你将事件监听器添加到父元素，而不是每个子元素分别添加。这在处理大量相似元素（如列表项）时特别有用。

```html
<ul id="todoList">
  <li>学习HTML</li>
  <li>学习CSS</li>
  <li>学习JavaScript</li>
</ul>
```

```javascript
// 不好的做法: 为每个li添加事件
const items = document.querySelectorAll('#todoList li');
items.forEach(item => {
  item.addEventListener('click', function() {
    console.log('点击了:', this.textContent);
  });
});

// 好的做法: 事件委托
document.getElementById('todoList').addEventListener('click', function(event) {
  // 检查事件源是否为li元素
  if (event.target.tagName === 'LI') {
    console.log('点击了:', event.target.textContent);
  }
});
```

事件委托的优势：
1. 减少事件处理程序的数量，提高性能
2. 动态添加的元素无需单独绑定事件
3. 内存占用更少

### 阻止传播：停止事件旅程

有时我们需要阻止事件继续传播，可以使用 `event.stopPropagation()` 方法：

```javascript
document.getElementById('inner').addEventListener('click', function(event) {
  console.log('内层div被点击了');
  event.stopPropagation(); // 阻止事件继续冒泡
});

document.getElementById('outer').addEventListener('click', function() {
  console.log('这不会被执行，因为事件传播被阻止了');
});
```

### 鼠标事件：指针交互

鼠标事件是网页交互中最常见的事件类型，它们让我们能够响应用户的鼠标操作。

```javascript
const element = document.getElementById('myElement');

// 单击事件
element.addEventListener('click', function() {
  console.log('元素被点击了');
});

// 双击事件
element.addEventListener('dblclick', function() {
  console.log('元素被双击了');
});

// 鼠标移入事件
element.addEventListener('mouseenter', function() {
  console.log('鼠标进入了元素');
  this.style.backgroundColor = 'lightblue';
});

// 鼠标移出事件
element.addEventListener('mouseleave', function() {
  console.log('鼠标离开了元素');
  this.style.backgroundColor = '';
});

// 鼠标移动事件
element.addEventListener('mousemove', function(event) {
  console.log(`鼠标位置: (${event.clientX}, ${event.clientY})`);
});
```

常见的鼠标事件差异：
- `mouseenter/mouseleave`：不会冒泡，仅当鼠标指针进入/离开元素时触发
- `mouseover/mouseout`：会冒泡，当鼠标指针进入/离开元素或其子元素时触发

### 键盘事件：键入交互

键盘事件让我们能够响应用户的键盘操作，常用于表单输入和快捷键等场景。

```javascript
const input = document.getElementById('myInput');

// 键盘按下事件
input.addEventListener('keydown', function(event) {
  console.log(`键盘按下: ${event.key}, 码值: ${event.keyCode}`);
});

// 键盘弹起事件
input.addEventListener('keyup', function(event) {
  console.log(`键盘弹起: ${event.key}`);
});

// 文本输入事件 (input事件比keypress更可靠)
input.addEventListener('input', function() {
  console.log('输入内容:', this.value);
});

// 实现快捷键
document.addEventListener('keydown', function(event) {
  // 检测Ctrl+S组合键
  if (event.ctrlKey && event.key === 's') {
    event.preventDefault(); // 阻止浏览器默认的保存行为
    console.log('触发了保存快捷键');
    saveData();
  }
});
```

注意：`keyCode` 属性已被废弃，建议使用 `key` 属性代替。

### 表单事件：用户输入

表单事件对于处理用户输入和表单提交非常重要，它们使我们能够验证数据、提供即时反馈等。

```javascript
const form = document.getElementById('myForm');
const nameInput = document.getElementById('nameInput');
const emailInput = document.getElementById('emailInput');

// 表单提交事件
form.addEventListener('submit', function(event) {
  event.preventDefault(); // 阻止表单默认提交行为

  // 执行表单验证
  if (nameInput.value.trim() === '') {
    alert('请输入姓名');
    return;
  }

  // 提交表单数据
  console.log('表单提交了，数据:', {
    name: nameInput.value,
    email: emailInput.value
  });

  // 可以在这里发送AJAX请求
});

// 输入变化事件
nameInput.addEventListener('input', function() {
  // 实时验证或提供反馈
  if (this.value.length < 2) {
    this.style.borderColor = 'red';
  } else {
    this.style.borderColor = 'green';
  }
});

// 失去焦点事件
emailInput.addEventListener('blur', function() {
  // 验证邮箱格式
  const isValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(this.value);
  if (!isValid && this.value !== '') {
    this.setCustomValidity('请输入有效的邮箱地址');
    this.reportValidity();
  } else {
    this.setCustomValidity('');
  }
});

// 重置事件
form.addEventListener('reset', function() {
  console.log('表单已重置');
});
```

### 文档事件：页面生命周期

文档事件让我们能够响应页面生命周期的不同阶段，如加载完成、关闭等。

```javascript
// 页面DOM加载完成事件
document.addEventListener('DOMContentLoaded', function() {
  console.log('DOM已加载完成');
  // 此时可以安全地操作DOM元素
  initApp();
});

// 页面完全加载完成事件(包括所有资源如图片、样式表等)
window.addEventListener('load', function() {
  console.log('页面已完全加载完成');
  hideLoadingScreen();
});

// 页面卸载前事件
window.addEventListener('beforeunload', function(event) {
  // 用户有未保存的更改时，提示确认
  if (hasUnsavedChanges()) {
    event.preventDefault();
    event.returnValue = ''; // 兼容旧版浏览器
    return '您有未保存的更改，确定要离开吗？';
  }
});

// 页面可见性变化事件
document.addEventListener('visibilitychange', function() {
  if (document.hidden) {
    console.log('页面不可见，暂停视频播放');
    pauseVideo();
  } else {
    console.log('页面可见，恢复应用状态');
    resumeAppState();
  }
});
```

### 事件创建：定制你自己的事件

除了浏览器内置的事件外，我们还可以创建自定义事件，以实现组件间的解耦和通信。

```javascript
// 创建自定义事件
const productAddedEvent = new CustomEvent('productAdded', {
  detail: {
    productId: 123,
    productName: '智能手表',
    price: 199.99
  },
  bubbles: true, // 允许事件冒泡
  cancelable: true // 允许事件被取消
});

// 创建简单的事件
const simpleEvent = new Event('simpleEvent', {
  bubbles: true,
  cancelable: false
});
```

### 事件分发：触发自定义事件

创建事件后，需要使用 `dispatchEvent` 方法将其分发到指定元素上。

```javascript
// 将事件分发到购物车元素
const cartElement = document.getElementById('shoppingCart');
cartElement.dispatchEvent(productAddedEvent);

// 简单事件分发示例
document.dispatchEvent(simpleEvent);
```

### 事件监听：接收自定义事件

监听自定义事件与监听内置事件的方式相同。

```javascript
// 监听自定义事件
cartElement.addEventListener('productAdded', function(event) {
  console.log('产品已添加到购物车:', event.detail.productName);
  updateCartCount();
  showNotification(`已添加商品: ${event.detail.productName}`);
});

// 监听简单事件
document.addEventListener('simpleEvent', function() {
  console.log('简单事件被触发了');
});
```

### 事件移除：清理事件监听器

当不再需要事件监听器时，应该移除它们以避免内存泄漏。

```javascript
function handleProductAdded(event) {
  console.log('产品已添加:', event.detail.productName);
}

// 添加事件监听器
cartElement.addEventListener('productAdded', handleProductAdded);

// 在不需要时移除事件监听器
cartElement.removeEventListener('productAdded', handleProductAdded);
```

### 1. 内存泄漏问题

```javascript
// 错误示范：创建闭包但不移除事件监听器
function setupHandler() {
  const data = { count: 0 };

  document.getElementById('button').addEventListener('click', function() {
    data.count++;
    console.log('计数:', data.count);
  });
  // 事件监听器持有data引用，导致data无法被垃圾回收
}

// 正确做法：保存函数引用以便于移除
function setupHandler() {
  const data = { count: 0 };
  const button = document.getElementById('button');

  function handleClick() {
    data.count++;
    console.log('计数:', data.count);
  }

  button.addEventListener('click', handleClick);

  // 提供清理方法
  return function cleanup() {
    button.removeEventListener('click', handleClick);
  };
}

const cleanup = setupHandler();
// 当不再需要时调用清理函数
// cleanup();
```

### 2. 事件委托中的目标判断

```javascript
// 错误示范：不精确的目标元素判断
document.getElementById('menu').addEventListener('click', function(event) {
  if (event.target.tagName === 'LI') {
    // 这可能会误判嵌套在LI里面的元素
    handleMenuItemClick(event.target);
  }
});

// 正确做法：使用closest方法查找最近的匹配元素
document.getElementById('menu').addEventListener('click', function(event) {
  const menuItem = event.target.closest('li');
  if (menuItem && this.contains(menuItem)) {
    handleMenuItemClick(menuItem);
  }
});
```

### 3. 事件处理程序中的this指向问题

```javascript
// 错误示范：在类方法中使用this可能导致指向错误
class Counter {
  constructor() {
    this.count = 0;
    this.button = document.getElementById('countButton');

    // 这里的this在事件处理程序中会指向按钮元素，而不是Counter实例
    this.button.addEventListener('click', function() {
      this.count++; // 错误: this.count是undefined
      console.log(this.count);
    });
  }
}

// 正确做法1：使用箭头函数
class Counter {
  constructor() {
    this.count = 0;
    this.button = document.getElementById('countButton');

    // 箭头函数不会改变this指向
    this.button.addEventListener('click', () => {
      this.count++;
      console.log(this.count);
    });
  }
}

// 正确做法2：使用bind方法
class Counter {
  constructor() {
    this.count = 0;
    this.button = document.getElementById('countButton');
    this.handleClick = this.handleClick.bind(this);

    this.button.addEventListener('click', this.handleClick);
  }

  handleClick() {
    this.count++;
    console.log(this.count);
  }
}
```

### 4. 事件处理中的性能问题

```javascript
// 错误示范：频繁触发的事件没有节流
window.addEventListener('scroll', function() {
  // 这个函数会在滚动时被频繁调用，可能导致性能问题
  updateScrollIndicator();
});

// 正确做法：使用节流函数限制执行频率
function throttle(func, limit) {
  let inThrottle;
  return function() {
    const args = arguments;
    const context = this;
    if (!inThrottle) {
      func.apply(context, args);
      inThrottle = true;
      setTimeout(() => inThrottle = false, limit);
    }
  };
}

// 限制每100ms最多执行一次
window.addEventListener('scroll', throttle(function() {
  updateScrollIndicator();
}, 100));
```

### IIFE（立即调用函数表达式）

```javascript
// 最早的模块化方式：使用立即调用函数表达式(IIFE)创建闭包
var myModule = (function() {
  // 私有变量，外部无法直接访问
  var privateVar = "我是私有变量";

  // 私有方法
  function privateMethod() {
    console.log(privateVar);
  }

  // 返回公共API
  return {
    // 公共方法
    publicMethod: function() {
      privateMethod();
      console.log("这是公共方法");
    },

    // 公共属性
    publicVar: "我是公共变量"
  };
})();

// 使用模块
myModule.publicMethod();  // 输出: "我是私有变量" "这是公共方法"
console.log(myModule.publicVar);  // 输出: "我是公共变量"
// console.log(myModule.privateVar);  // 错误，无法访问
```

IIFE是JavaScript最早的模块化模式之一，它利用函数作用域和闭包创建私有空间，避免变量污染全局命名空间。这种模式虽然简单，但已经体现了模块化的核心思想：封装实现细节，只暴露必要的接口。

### CommonJS

```javascript
// 在Node.js中使用CommonJS（math.js）
function add(a, b) {
  return a + b;
}

function subtract(a, b) {
  return a - b;
}

// 导出模块
module.exports = {
  add: add,
  subtract: subtract
};

// 在另一个文件中导入和使用（app.js）
const math = require('./math');
console.log(math.add(5, 3));  // 输出: 8
```

CommonJS规范源于Node.js，它定义了一套完整的模块系统，包括模块定义、导出和导入机制。这种同步加载的模式非常适合服务器环境，但在浏览器中可能导致性能问题，因此出现了AMD等异步加载解决方案。

### AMD（异步模块定义）

```javascript
// 使用RequireJS实现AMD
// 定义模块（math.js）
define('math', [], function() {
  return {
    add: function(a, b) {
      return a + b;
    },
    subtract: function(a, b) {
      return a - b;
    }
  };
});

// 使用模块
require(['math'], function(math) {
  console.log(math.add(5, 3));  // 输出: 8
});
```

AMD（Asynchronous Module Definition）专为浏览器环境设计，支持异步加载模块，避免阻塞页面渲染。RequireJS是实现AMD规范的最流行库之一，它通过`define`定义模块，通过`require`加载模块。

### CMD（通用模块定义）

```javascript
// 使用SeaJS实现CMD
// 定义模块（math.js）
define(function(require, exports, module) {
  exports.add = function(a, b) {
    return a + b;
  };

  exports.subtract = function(a, b) {
    return a - b;
  };
});

// 使用模块
define(function(require, exports, module) {
  var math = require('math');
  console.log(math.add(5, 3));  // 输出: 8
});
```

CMD（Common Module Definition）是SeaJS推广的规范，与AMD类似，但更接近CommonJS的写法。最大的区别在于加载时机：AMD推崇依赖前置，在定义模块时就声明所有依赖；而CMD推崇依赖就近，在需要时再加载依赖。

### 模块语法

```javascript
// 模块基本语法（math.js）
// 导出单个功能
export function add(a, b) {
  return a + b;
}

// 导出多个功能
export function subtract(a, b) {
  return a - b;
}

// 默认导出
export default function multiply(a, b) {
  return a * b;
}

// 在另一个文件中导入（app.js）
// 导入单个功能
import { add } from './math.js';

// 导入多个功能
import { add, subtract } from './math.js';

// 导入全部功能并命名
import * as math from './math.js';

// 导入默认导出
import multiply from './math.js';

// 混合导入
import multiply, { add, subtract } from './math.js';
```

ES Modules (ESM) 是ECMAScript官方的模块系统，现在已被所有现代浏览器和Node.js支持。与之前的解决方案相比，ESM有以下优势：
- 静态结构，支持编译时优化
- 支持循环依赖
- 异步加载
- 更好的错误检查

### 导入导出

```javascript
// 导出变量
export const PI = 3.14159;

// 导出类
export class Person {
  constructor(name) {
    this.name = name;
  }

  greet() {
    return `你好，我是${this.name}`;
  }
}

// 重命名导出
function helper() { /* ... */ }
export { helper as utilHelper };

// 重命名导入
import { utilHelper as helper } from './utils.js';

// 组合模块
import * as utils from './utils.js';
export { utils };

// 重新导出
export { formatDate } from './date-utils.js';
```

ESM的导入导出语法灵活多样，可以满足各种模块组织需求。需要注意的是，导入的模块是只读的，无法直接修改导入的变量或函数。

### 动态导入

```javascript
// 静态导入（始终加载）
import { add } from './math.js';

// 动态导入（按需加载）
button.addEventListener('click', async () => {
  try {
    // 用户点击时才加载模块
    const { default: Chart } = await import('./chart.js');
    const chart = new Chart();
    chart.render('#container');
  } catch (error) {
    console.error('加载图表模块失败:', error);
  }
});
```

ES2020引入的动态`import()`是一个游戏规则改变者，它返回一个Promise，支持按需加载模块，非常适合代码分割和懒加载场景，可以显著提升应用的性能和用户体验。

### 模块特性

```javascript
// 模块作用域
// 在模块A中
const message = "模块A";
console.log(message);  // "模块A"

// 在模块B中
const message = "模块B";  // 不会冲突
console.log(message);  // "模块B"

// 默认严格模式
// 在非模块脚本中
x = 10;  // 在非严格模式下允许
console.log(window.x);  // 10

// 在模块中
x = 10;  // 错误: "x is not defined" (严格模式)

// 单次求值
// math.js
console.log("模块初始化");
export const value = "exported value";

// 即使多次导入，模块代码也只执行一次
import { value } from './math.js';  // 输出: "模块初始化"
import { value } from './math.js';  // 无输出，模块已初始化
```

ESM具有以下重要特性：
1. 模块作用域：每个模块有自己的作用域，不会污染全局
2. 严格模式：模块自动运行在严格模式下，无需手动添加`"use strict"`
3. 顶层`this`为`undefined`，而非全局对象
4. 单次求值：无论导入多少次，模块代码只执行一次
5. 支持静态分析，便于工具优化
6. 文件自动延迟加载，类似于添加了`defer`属性

### Webpack

```javascript
// webpack.config.js
const path = require('path');

module.exports = {
  entry: './src/index.js',
  output: {
    filename: 'bundle.js',
    path: path.resolve(__dirname, 'dist'),
  },
  module: {
    rules: [
      {
        test: /\.js$/,
        exclude: /node_modules/,
        use: {
          loader: 'babel-loader',
          options: {
            presets: ['@babel/preset-env']
          }
        }
      }
    ]
  }
};
```

Webpack是最流行的前端构建工具之一，它将模块依赖转化为静态资源。核心功能包括：
- 多种模块格式支持（ESM、CommonJS、AMD）
- 丰富的加载器（Loaders）处理各类资源
- 代码分割与懒加载
- 热模块替换（HMR）
- 通过插件系统扩展功能

### Rollup

```javascript
// rollup.config.js
export default {
  input: 'src/main.js',
  output: {
    file: 'bundle.js',
    format: 'esm',  // 也支持'cjs', 'amd', 'umd'等
    sourcemap: true
  },
  plugins: [
    // 各种插件配置
  ]
};
```

Rollup专注于ES Modules，以生成更高效、更小的包为主要目标。它的特点包括：
- 树摇（Tree Shaking）：自动移除未使用的代码
- 输出多种格式（ESM、CommonJS、UMD等）
- 简洁的API和配置
- 适合库和工具的开发

### Vite

```javascript
// vite.config.js
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  server: {
    port: 3000
  },
  build: {
    outDir: 'dist',
    minify: 'terser'
  }
});
```

Vite是新一代的前端构建工具，由Vue.js的创建者尤雨溪开发。它利用浏览器原生ESM支持，实现了极速的开发服务器和优化的生产构建：
- 开发环境无需打包，按需编译
- 快速的冷启动和即时热更新
- 预配置的构建优化
- 丰富的插件生态
- 通用的配置，支持多个框架

### 打包优化

```javascript
// webpack代码分割配置
module.exports = {
  // ...其他配置
  optimization: {
    splitChunks: {
      chunks: 'all',
      // 抽取共用模块到单独的chunk
      cacheGroups: {
        vendor: {
          test: /[\\/]node_modules[\\/]/,
          name: 'vendors',
          chunks: 'all'
        }
      }
    }
  }
};

// 动态导入实现懒加载
const loadProfilePage = () => import(/* webpackChunkName: "profile" */ './profile.js');

// 按需加载组件
button.addEventListener('click', () => {
  loadProfilePage().then(module => {
    module.renderProfile();
  });
});
```

现代构建工具提供了多种优化策略，帮助改善应用性能：
- 代码分割：将应用拆分为多个小包，按需加载
- 树摇：删除未使用的代码
- 懒加载：推迟加载非关键资源
- 压缩和混淆：减小文件体积
- 作用域提升：扁平化模块，减少运行时开销
- 缓存优化：通过内容哈希实现持久缓存

### 模块设计

```javascript
// 单一职责原则
// 不好的实践: 一个模块做太多事情
export function formatDate() { /* ... */ }
export function validateEmail() { /* ... */ }
export function calculateTax() { /* ... */ }

// 好的实践: 模块专注于单一功能领域
// date-utils.js
export function formatDate() { /* ... */ }
export function parseDate() { /* ... */ }

// validation.js
export function validateEmail() { /* ... */ }
export function validatePhone() { /* ... */ }

// 显式依赖
// 好的实践: 清晰声明依赖
import { formatCurrency } from './currency.js';
import { getUser } from './api.js';

export function renderUserBalance(userId) {
  const user = getUser(userId);
  return formatCurrency(user.balance);
}
```

模块设计的关键原则包括：
- 单一职责：每个模块应该专注于一个功能领域
- 封装实现细节：只暴露必要的API
- 明确依赖：显式导入依赖，避免隐式依赖
- 小而专：保持模块小巧、专一，易于理解和维护
- 接口稳定：谨慎修改公共API，保持向后兼容

### 依赖管理

```javascript
// package.json中的依赖版本管理
{
  "dependencies": {
    // 最好指定确切版本，增加可预测性
    "lodash": "4.17.21",

    // 或者使用语义化版本范围
    "react": "^17.0.2",  // 兼容17.0.2及更高的17.x版本
    "vue": "~3.2.0"      // 兼容3.2.x版本
  },
  "devDependencies": {
    "webpack": "^5.65.0"
  }
}

// 使用peerDependencies声明同级依赖
{
  "name": "my-react-library",
  "peerDependencies": {
    "react": "^16.8.0 || ^17.0.0"
  }
}
```

良好的依赖管理可以提升项目的稳定性和可维护性：
- 谨慎添加依赖，评估必要性和质量
- 指定明确的版本号，避免意外升级
- 定期更新依赖，修复安全漏洞
- 使用lock文件（package-lock.json、yarn.lock）锁定精确版本
- 为库使用peerDependencies声明宿主环境依赖
- 考虑使用monorepo管理多包项目

### 性能优化

```javascript
// 按路由分割代码
// App.js (使用React Router)
import { lazy, Suspense } from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';

// 懒加载组件
const Home = lazy(() => import('./pages/Home'));
const About = lazy(() => import('./pages/About'));
const Dashboard = lazy(() => import('./pages/Dashboard'));

function App() {
  return (
    <BrowserRouter>
      <Suspense fallback={<div>Loading...</div>}>
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/about" element={<About />} />
          <Route path="/dashboard" element={<Dashboard />} />
        </Routes>
      </Suspense>
    </BrowserRouter>
  );
}

// 按需加载第三方库
async function createChart(container, data) {
  // 只在需要时加载大型图表库
  const { Chart } = await import('chart.js/auto');
  return new Chart(container, {
    type: 'bar',
    data
  });
}
```

模块化相关的性能优化技巧：
- 路由级代码分割：按路由拆分代码，减少初始加载时间
- 组件级懒加载：延迟加载非关键UI组件
- 按需导入第三方库：尤其是体积较大的库
- 预加载关键路径：在空闲时预加载即将需要的模块
- 减少依赖体积：选择轻量级库或使用部分导入
- 模块预构建：将大型依赖预先打包，减少开发时的加载开销

# JavaScript 运算符与表达式：写给小白的完全指南

## 引言

还记得小学时学习的数学符号吗？加号、减号、乘号和除号，这些都是我们的老朋友了。在JavaScript中，这些符号有了新名字：**运算符**。运算符是编程语言的"动词"，它们让代码能够"做事情"。无论是计算购物车总价，判断用户是否登录，还是组合多个条件进行判断，运算符都在默默工作。作为前端开发的基础，掌握运算符就像学会使用厨师的刀具一样重要 - 没有它们，你几乎寸步难行。

本文将用最通俗的语言，带你彻底掌握JavaScript中的各类运算符，让你不仅知道"怎么用"，更明白"为什么"和"最佳实践"。

## 算术运算符：数学运算的好帮手

算术运算符可能是你接触的第一批JavaScript运算符，它们让我们能进行基本的数学计算。

### 加减乘除：最常见的四大运算

```javascript
// 加法运算
let price = 99;
let tax = 7;
let total = price + tax; // 结果: 106
console.log(`商品总价: ¥${total}`); // 商品总价: ¥106

// 减法运算
let budget = 1000;
let expense = 650;
let remaining = budget - expense; // 结果: 350
console.log(`剩余预算: ¥${remaining}`); // 剩余预算: ¥350

// 乘法运算
let quantity = 5;
let unitPrice = 20;
let subtotal = quantity * unitPrice; // 结果: 100
console.log(`小计: ¥${subtotal}`); // 小计: ¥100

// 除法运算
let totalDistance = 240;
let days = 3;
let dailyAverage = totalDistance / days; // 结果: 80
console.log(`日均行走: ${dailyAverage}公里`); // 日均行走: 80公里
```

### 取余（%）：计算余数的工具

取余运算符（%）返回除法后的余数，这在判断偶数/奇数、循环操作时特别有用。

```javascript
// 判断奇偶数
let number = 15;
let remainder = number % 2;
console.log(remainder); // 结果: 1 (奇数)

// 实用场景：轮播图循环显示
let slides = 5; // 有5张幻灯片
let currentPosition = 7; // 当前是第7次点击"下一张"
let actualSlide = currentPosition % slides; // 结果: 2 (表示应该显示第3张幻灯片)
console.log(`显示第${actualSlide + 1}张幻灯片`); // 显示第3张幻灯片
```

### 自增自减：计数器的好助手

自增（++）和自减（--）让变量值加1或减1，非常适合计数场景。

```javascript
// 自增 (++)
let visitors = 0;
visitors++; // 等同于 visitors = visitors + 1
console.log(`访问人数: ${visitors}`); // 访问人数: 1

// 自减 (--)
let countdown = 10;
countdown--; // 等同于 countdown = countdown - 1
console.log(`倒计时: ${countdown}秒`); // 倒计时: 9秒

// 前置与后置的区别
let a = 5;
let b = a++; // 后置: 先赋值后自增
console.log(a, b); // 6, 5

let c = 5;
let d = ++c; // 前置: 先自增后赋值
console.log(c, d); // 6, 6
```

### 幂运算（**）：计算乘方

```javascript
// 计算乘方
let base = 2;
let exponent = 3;
let result = base ** exponent; // 等同于 Math.pow(2, 3)
console.log(`${base}的${exponent}次方 = ${result}`); // 2的3次方 = 8
```

## 比较运算符：做决策的基础

比较运算符用于比较值，返回布尔值（true或false），是条件语句的基础。

### 相等比较（==）与严格相等（===）：最容易混淆的运算符

```javascript
// 相等比较 (==): 仅比较值，会进行类型转换
console.log(5 == "5"); // true，因为字符串"5"会被转换为数字5

// 严格相等 (===): 同时比较值和类型
console.log(5 === "5"); // false，因为类型不同（一个是数字，一个是字符串）

// 为什么要优先使用===？看看下面的例子
console.log(0 == ""); // true，这可能导致意外行为
console.log(0 === ""); // false，类型安全，避免隐式转换带来的问题
```

### 大小比较：比大小

```javascript
let age = 18;

// 大于 (>)
console.log(age > 16); // true，表示年龄大于16岁

// 小于 (<)
console.log(age < 21); // true，表示年龄小于21岁

// 大于等于 (>=)
console.log(age >= 18); // true，表示年龄大于或等于18岁

// 小于等于 (<=)
console.log(age <= 20); // true，表示年龄小于或等于20岁
```

### 不等比较（!=和!==）：检查不同

```javascript
// 不相等 (!=): 值不相等（进行类型转换）
console.log(5 != "6"); // true，因为5和6不相等

// 严格不相等 (!==): 值或类型不相等
console.log(5 !== "5"); // true，因为类型不同
```

## 逻辑运算符：组合条件的能手

逻辑运算符用于组合多个条件，让我们能够进行复杂的逻辑判断。

### 与运算（&&）：所有条件都必须为真

想象一下判断一个人是否能看R级电影：必须年满18岁**并且**有有效身份证。

```javascript
let age = 19;
let hasID = true;

// 只有两个条件都为true，结果才为true
let canWatchRMovie = age >= 18 && hasID;
console.log(`能否观看限制级电影: ${canWatchRMovie}`); // 能否观看限制级电影: true

// 如果任一条件为false，结果都为false
let youngAge = 16;
let canYoungWatch = youngAge >= 18 && hasID;
console.log(`年轻人能否观看: ${canYoungWatch}`); // 年轻人能否观看: false
```

### 或运算（||）：至少一个条件为真

想象一下判断是否符合优惠条件：学生**或者**老人可以享受折扣。

```javascript
let isStudent = false;
let isSenior = true;

// 只要有一个条件为true，结果就为true
let hasDiscount = isStudent || isSenior;
console.log(`是否享受折扣: ${hasDiscount}`); // 是否享受折扣: true

// 只有所有条件都是false，结果才为false
let isRegularCustomer = !isStudent && !isSenior;
console.log(`是否普通客户: ${isRegularCustomer}`); // 是否普通客户: false
```

### 非运算（!）：取反

非运算符可以将布尔值反转。

```javascript
let isLoggedIn = false;
let needsToLogin = !isLoggedIn; // 取反
console.log(`需要登录: ${needsToLogin}`); // 需要登录: true

// 双重否定(!!)常用于将值转换为布尔类型
console.log(!!0); // false (0被视为假值)
console.log(!!1); // true (非0数字被视为真值)
console.log(!!""); // false (空字符串被视为假值)
console.log(!!"hello"); // true (非空字符串被视为真值)
```

### 短路运算：逻辑运算符的省力技巧

短路运算是逻辑运算符的一个重要特性，它会在得到确定结果后停止运算，这能帮我们编写更简洁的代码。

```javascript
// &&短路：如果第一个条件为false，就不会检查第二个条件
function getDogName() {
  console.log("getDogName被调用了");
  return "旺财";
}

let hasDog = false;
let dogName = hasDog && getDogName(); // getDogName不会被调用
console.log(dogName); // false

// ||短路：如果第一个条件为true，就不会检查第二个条件
let username = "小明"; // 假设用户已提供用户名
let defaultName = "游客";
let displayName = username || defaultName; // 如果username存在，就使用username
console.log(`欢迎, ${displayName}!`); // 欢迎, 小明!
```

## 其他实用运算符

### 三元运算符：简化的if-else

三元运算符是if-else的简洁形式，格式为：`条件 ? 为真时的值 : 为假时的值`。

```javascript
let age = 16;
let message = age >= 18 ? "你可以投票" : "你还不能投票";
console.log(message); // 你还不能投票

// 等价的if-else写法
let messageIfElse;
if (age >= 18) {
  messageIfElse = "你可以投票";
} else {
  messageIfElse = "你还不能投票";
}
```

### 可选链运算符（?.）：安全访问对象属性

可选链运算符让我们能安全地访问可能不存在的对象属性，避免报错。

```javascript
// 假设从API获取的用户数据可能不完整
let user = {
  name: "张三",
  // address属性不存在
};

// 不使用可选链：可能导致错误
// let city = user.address.city; // 报错：Cannot read property 'city' of undefined

// 使用可选链：安全访问
let city = user.address?.city; // 结果: undefined，不会报错
console.log(`城市: ${city || '未提供'}`); // 城市: 未提供

// 可选链也适用于方法调用
let result = user.getDetails?.(); // 如果getDetails方法存在则调用，否则返回undefined
```

### 空值合并运算符（??）：提供默认值

空值合并运算符在值为null或undefined时提供默认值。

```javascript
let username = null;
let displayName = username ?? "游客"; // 如果username为null或undefined，使用"游客"
console.log(`欢迎, ${displayName}!`); // 欢迎, 游客!

// ??与||的区别
let count = 0;
let defaultCount = 10;

// ||会将0视为假值，因此返回默认值
let result1 = count || defaultCount;
console.log(result1); // 10

// ??只在值为null或undefined时使用默认值，0是有效值
let result2 = count ?? defaultCount;
console.log(result2); // 0
```

## 常见错误与注意事项

### 1. 相等比较混淆（==与===）

```javascript
// 错误示例
if (userId == null) {
  // 问题: 这会同时检查null和undefined，可能不是你想要的行为
}

// 正确示例
if (userId === null) {
  // 明确检查是否为null
}

// 另一个正确示例：如果需要同时检查null和undefined
if (userId == null) {
  // 等同于 userId === null || userId === undefined
}
```

### 2. 运算符优先级问题

```javascript
// 错误示例
let result = 2 + 3 * 5; // 期望: 25，实际: 17

// 正确示例：使用括号明确运算顺序
let result = (2 + 3) * 5; // 结果: 25
```

### 3. 短路评估引起的意外行为

```javascript
// 错误示例
function processUser(user) {
  let name = user && user.name; // 如果user是0或空字符串，会返回user而不是undefined
}

// 正确示例
function processUser(user) {
  let name = user?.name; // 只在user为null或undefined时返回undefined
}
```

### 4. 自增/自减位置的影响

```javascript
// 容易混淆的例子
let a = 1;
let b = a++;
console.log(a, b); // 2, 1 - 可能不是期望的结果

// 避免在复杂表达式中使用自增/自减
let c = 1;
let d = ++c + c++; // 避免这种写法
```

## 总结

### prototype 属性

```javascript
// 函数才有prototype属性
function Person(name) {
  this.name = name;
}

Person.prototype.sayHello = function() {
  console.log(`你好，我是${this.name}`);
};

let person1 = new Person("小明");
person1.sayHello();  // 输出: 你好，我是小明
```

每个函数都有一个`prototype`属性，指向一个对象。当这个函数被用作构造函数时，新创建的对象会将这个函数的`prototype`作为自己的原型。

### 原型链继承

```javascript
function Animal(name) {
  this.name = name;
  this.colors = ["黑", "白"];
}

Animal.prototype.eat = function() {
  console.log(`${this.name}正在吃东西`);
};

function Dog(name) {
  this.type = "狗";
}

// 设置原型链关系
Dog.prototype = new Animal("旺财");

let dog = new Dog();
dog.eat();  // 输出: 旺财正在吃东西
console.log(dog.colors);  // 输出: ["黑", "白"]
```

优点：简单，子类能访问父类原型上的方法。
缺点：所有实例共享父类实例属性，无法向父类构造函数传参。

### 构造函数继承

```javascript
function Animal(name) {
  this.name = name;
  this.colors = ["黑", "白"];
}

Animal.prototype.eat = function() {
  console.log(`${this.name}正在吃东西`);
};

function Dog(name) {
  // 调用父类构造函数
  Animal.call(this, name);
  this.type = "狗";
}

let dog = new Dog("小黑");
console.log(dog.name);  // 输出: 小黑
console.log(dog.colors);  // 输出: ["黑", "白"]
// dog.eat();  // 错误: dog.eat is not a function
```

优点：可以向父类构造函数传参，实例不共享父类属性。
缺点：无法继承父类原型上的方法，每个实例都会创建父类方法的副本。

### 组合继承

```javascript
function Animal(name) {
  this.name = name;
  this.colors = ["黑", "白"];
}

Animal.prototype.eat = function() {
  console.log(`${this.name}正在吃东西`);
};

function Dog(name) {
  // 继承属性
  Animal.call(this, name);
  this.type = "狗";
}

// 继承方法
Dog.prototype = new Animal();
Dog.prototype.constructor = Dog;  // 修复constructor指向

let dog = new Dog("小黑");
dog.eat();  // 输出: 小黑正在吃东西
dog.colors.push("黄");
console.log(dog.colors);  // 输出: ["黑", "白", "黄"]

let dog2 = new Dog("小白");
console.log(dog2.colors);  // 输出: ["黑", "白"], 不受dog影响
```

优点：结合了上述两种方式的优点。
缺点：父类构造函数被调用两次，效率较低。

### 原型式继承

```javascript
function object(o) {
  function F() {}
  F.prototype = o;
  return new F();
}

let animal = {
  name: "动物",
  colors: ["黑", "白"],
  eat: function() {
    console.log(`${this.name}正在吃东西`);
  }
};

let dog = object(animal);
dog.name = "小黑";
dog.eat();  // 输出: 小黑正在吃东西

// ES5提供了简化方法
let dog2 = Object.create(animal);
```

优点：简单，不需要构造函数。
缺点：共享引用类型属性，与原型链继承类似。

### 寄生式继承

```javascript
function createDog(original) {
  let clone = Object.create(original);
  clone.bark = function() {
    console.log("汪汪汪！");
  };
  return clone;
}

let animal = {
  name: "动物",
  eat: function() {
    console.log(`${this.name}正在吃东西`);
  }
};

let dog = createDog(animal);
dog.bark();  // 输出: 汪汪汪！
dog.eat();   // 输出: 动物正在吃东西
```

优点：在原型式继承基础上增强对象。
缺点：函数不能复用，每次创建都会生成新函数。

### 寄生组合式继承

```javascript
function inheritPrototype(subType, superType) {
  let prototype = Object.create(superType.prototype);
  prototype.constructor = subType;
  subType.prototype = prototype;
}

function Animal(name) {
  this.name = name;
  this.colors = ["黑", "白"];
}

Animal.prototype.eat = function() {
  console.log(`${this.name}正在吃东西`);
};

function Dog(name) {
  Animal.call(this, name);
  this.type = "狗";
}

inheritPrototype(Dog, Animal);

Dog.prototype.bark = function() {
  console.log("汪汪汪！");
};

let dog = new Dog("小黑");
dog.eat();  // 输出: 小黑正在吃东西
dog.bark();  // 输出: 汪汪汪！
```

优点：只调用一次父类构造函数，保持原型链，是引用类型最理想的继承方式。
缺点：实现较复杂。

### class 关键字

```javascript
class Animal {
  constructor(name) {
    this.name = name;
    this.colors = ["黑", "白"];
  }

  eat() {
    console.log(`${this.name}正在吃东西`);
  }
}

let animal = new Animal("动物");
animal.eat();  // 输出: 动物正在吃东西
```

`class`关键字提供了更清晰的语法来定义类，但实际上是原型继承的语法糖。

### extends 与 super

```javascript
class Dog extends Animal {
  constructor(name) {
    super(name);  // 调用父类构造函数
    this.type = "狗";
  }

  bark() {
    console.log("汪汪汪！");
  }

  // 重写父类方法
  eat() {
    super.eat();  // 调用父类方法
    console.log("狗喜欢啃骨头");
  }
}

let dog = new Dog("小黑");
dog.eat();
// 输出:
// 小黑正在吃东西
// 狗喜欢啃骨头
```

`extends`关键字设置继承关系，`super`关键字用于调用父类的构造函数和方法。

### 静态方法继承

```javascript
class Animal {
  static isAnimal(obj) {
    return obj instanceof Animal;
  }
}

class Dog extends Animal {
  static isDog(obj) {
    return obj instanceof Dog;
  }
}

console.log(Dog.isAnimal(new Dog()));  // true，继承了父类的静态方法
```

子类自动继承父类的静态方法，这在ES5中需要手动实现。

### 私有属性与方法

```javascript
class Animal {
  // 公有属性
  name;

  // 私有属性（ES2022标准）
  #age;

  constructor(name, age) {
    this.name = name;
    this.#age = age;
  }

  // 私有方法
  #calculateLifeExpectancy() {
    return this.#age * 3;
  }

  getInfo() {
    console.log(`${this.name}的预期寿命是${this.#calculateLifeExpectancy()}年`);
  }
}

let animal = new Animal("猫", 5);
animal.getInfo();  // 输出: 猫的预期寿命是15年
// console.log(animal.#age);  // 语法错误：私有字段不可访问
```

私有字段和方法使用`#`前缀，只能在类内部访问，有助于封装实现细节。

### 继承内置类型

```javascript
// 扩展内置Array类
class MyArray extends Array {
  first() {
    return this[0];
  }

  last() {
    return this[this.length - 1];
  }
}

let arr = new MyArray(1, 2, 3, 4);
console.log(arr.first());  // 1
console.log(arr.last());   // 4
console.log(arr.length);   // 4
console.log(arr instanceof Array);  // true
```

ES6允许继承内置类型，这在ES5中很难实现。继承内置类型可以扩展它们的功能，同时保留原有特性。

### 使用原型优化性能

```javascript
// 不优化的写法
function Person(name, age) {
  this.name = name;
  this.age = age;
  this.sayHello = function() {
    console.log(`你好，我是${this.name}`);
  };
}

// 优化后的写法
function Person(name, age) {
  this.name = name;
  this.age = age;
}

Person.prototype.sayHello = function() {
  console.log(`你好，我是${this.name}`);
};
```

将方法定义在原型上而非实例中，可以节省内存，提高性能。因为所有实例共享同一个方法，而不是每个实例都创建一个方法副本。

### 多态实现

```javascript
// 基类
function Animal() {}
Animal.prototype.makeSound = function() {
  console.log("动物发出声音");
};

// 子类
function Dog() {}
Dog.prototype = Object.create(Animal.prototype);
Dog.prototype.makeSound = function() {
  console.log("汪汪汪！");
};

function Cat() {}
Cat.prototype = Object.create(Animal.prototype);
Cat.prototype.makeSound = function() {
  console.log("喵喵喵！");
};

// 多态使用
function animalSound(animal) {
  animal.makeSound();
}

animalSound(new Dog());  // 输出: 汪汪汪！
animalSound(new Cat());  // 输出: 喵喵喵！
```

通过原型继承和方法重写，JavaScript可以实现类似其他语言的多态性。

### 工厂模式结合

```javascript
// 定义基础原型
const carPrototype = {
  init(model, color) {
    this.model = model;
    this.color = color;
    return this;
  },
  getInfo() {
    return `这是一辆${this.color}色的${this.model}`;
  }
};

// 工厂函数
function createCar(model, color) {
  return Object.create(carPrototype).init(model, color);
}

// 使用工厂创建对象
const car1 = createCar("特斯拉", "黑");
const car2 = createCar("宝马", "白");

console.log(car1.getInfo());  // 输出: 这是一辆黑色的特斯拉
console.log(car2.getInfo());  // 输出: 这是一辆白色的宝马
```

结合工厂模式和原型模式，可以灵活创建共享行为的对象，同时保持代码的组织性。

### 原型设计模式

```javascript
// 原型对象
const personPrototype = {
  greeting: function() {
    console.log(`你好，我是${this.name}`);
  },
  farewell: function() {
    console.log(`再见，${this.name}要走了`);
  }
};

// 创建实例
function createPerson(name) {
  const person = Object.create(personPrototype);
  person.name = name;
  return person;
}

const person1 = createPerson("小明");
person1.greeting();  // 输出: 你好，我是小明

// 扩展原型
const studentPrototype = Object.create(personPrototype);
studentPrototype.study = function() {
  console.log(`${this.name}正在学习`);
};

function createStudent(name, school) {
  const student = Object.create(studentPrototype);
  student.name = name;
  student.school = school;
  return student;
}

const student1 = createStudent("小红", "某大学");
student1.greeting();  // 输出: 你好，我是小红
student1.study();     // 输出: 小红正在学习
```

原型设计模式允许通过克隆现有对象来创建新对象，避免了显式创建类的过程，适合动态环境。

### 原型污染

```javascript
// 危险操作
Object.prototype.customMethod = function() {
  console.log("我被添加到了所有对象上");
};

let obj = {};
obj.customMethod();  // 输出: 我被添加到了所有对象上

// 更危险的例子
Object.prototype.hasOwnProperty = function() {
  return false;
};  // 这会破坏许多依赖hasOwnProperty的代码
```

修改内置对象的原型（如`Object.prototype`）可能导致意外行为。最佳实践是避免修改内置对象原型，如需扩展，可以使用子类化或组合。

### 继承深度问题

```javascript
// 继承链太长
function A() {}
function B() {}
B.prototype = new A();
function C() {}
C.prototype = new B();
function D() {}
D.prototype = new C();
// ...更多层级

const instance = new D();
// 访问属性时需要遍历整个原型链，影响性能
```

过深的继承链会影响属性查找效率。建议保持继承层次相对扁平，避免过复杂的继承结构。

### this 指向问题

```javascript
function Person(name) {
  this.name = name;
}

Person.prototype.sayHello = function() {
  console.log(`你好，我是${this.name}`);
};

const person = new Person("小明");

// 正常调用
person.sayHello();  // 输出: 你好，我是小明

// 问题情况
const greet = person.sayHello;
greet();  // 输出: 你好，我是undefined (因为this指向全局对象或undefined)

// 解决方法
const boundGreet = person.sayHello.bind(person);
boundGreet();  // 输出: 你好，我是小明
```

方法中的`this`指向调用该方法的对象，而不是定义该方法的对象。这是JavaScript中常见的混淆点，尤其在事件处理和回调函数中。

### 属性查找性能

```javascript
// 低效属性查找
function findProp(obj, prop) {
  return obj[prop];  // 可能需要遍历整个原型链
}

// 更高效的实现
function findOwnProp(obj, prop) {
  return obj.hasOwnProperty(prop) ? obj[prop] : undefined;
}
```

属性查找需要遍历原型链，对于频繁访问的属性，可以考虑将其直接定义在实例上，或使用闭包来避免原型查找。

```javascript
function calculateTotal() {
  // price只在函数内部可见
  let price = 100;
  let tax = price * 0.1;
  let total = price + tax;

  console.log(`总价: ¥${total}`);
  return total;
}

calculateTotal(); // 输出: "总价: ¥110"

// 尝试在函数外部访问函数内的变量
// console.log(price); // 错误: price is not defined
```

函数作用域提供了**封装**，保护变量不被外部代码意外修改，这是构建可靠代码的重要特性。

### 块级作用域：临时的隔离区

块级作用域是ES6（ECMAScript 2015）引入的概念，它将变量的可见性限制在一个代码块（由花括号`{}`定义）内。使用`let`和`const`声明的变量具有块级作用域。

```javascript
// if语句创建了一个块级作用域
if (true) {
  let blockScoped = "我只在这个块中可见";
  var notBlockScoped = "我在外部也可见";
  const alsoBlockScoped = "我也只在块中可见";

  console.log(blockScoped); // 正常工作
}

// console.log(blockScoped); // 错误: blockScoped is not defined
// console.log(alsoBlockScoped); // 错误: alsoBlockScoped is not defined
console.log(notBlockScoped); // 可以访问，输出: "我在外部也可见"

// for循环也创建块级作用域
for (let i = 0; i < 3; i++) {
  // i只在循环内部可见
}
// console.log(i); // 错误: i is not defined
```

块级作用域让我们可以在更精细的层次上控制变量的可见性，减少命名冲突和意外修改。

### 词法作用域：固定的地址簿

词法作用域（也称为静态作用域）是JavaScript的一个基本特性。它决定了一个变量的可见性是由源代码中变量定义的位置决定的，而不是由函数调用的位置决定。

```javascript
let name = "全局名称";

function outer() {
  let name = "张三";

  function inner() {
    // inner函数可以访问它自己的作用域、outer函数的作用域和全局作用域
    console.log(`你好, ${name}`); // 使用outer函数中的name
  }

  inner();
}

outer(); // 输出: "你好, 张三"
```

词法作用域是理解闭包的关键基础。它意味着函数可以访问它被定义时所处环境中的变量，即使该函数在其他地方被调用。

## 变量生命周期：从出生到消亡

变量的生命周期与作用域密切相关，但它们不完全相同。生命周期描述了变量从创建到销毁的整个过程。

### 变量声明：变量的诞生方式

JavaScript提供了三种主要的变量声明方式，每种都有不同的特性：

```javascript
// 使用var（老式，有特殊的提升行为）
var oldWay = "我是用var声明的";

// 使用let（现代，可重新赋值）
let modern = "我是用let声明的";
modern = "我可以被修改";

// 使用const（现代，不可重新赋值）
const constant = "我是用const声明的";
// constant = "尝试修改"; // 错误: Assignment to constant variable

// 不使用关键字（不推荐，会创建全局变量）
function badPractice() {
  unintentionalGlobal = "我会变成全局变量"; // 缺少声明关键字
}
badPractice();
console.log(unintentionalGlobal); // 可以访问，因为它变成了全局变量
```

**最佳实践**：
- 优先使用`const`声明不需要重新赋值的变量
- 使用`let`声明需要重新赋值的变量
- 避免使用`var`（除非有特殊原因）
- 永远不要省略声明关键字

### 变量提升：奇怪的先斩后奏

变量提升是JavaScript的一个特性，它会将变量和函数声明在代码执行前"提升"到当前作用域的顶部。但这种提升行为对`var`、`let/const`和函数声明的影响各不相同。

```javascript
// 使用var的提升
console.log(hoistedVar); // 输出: undefined（而不是报错）
var hoistedVar = "我被提升了，但只有声明部分";

// 等同于：
// var hoistedVar;
// console.log(hoistedVar);
// hoistedVar = "我被提升了，但只有声明部分";

// 使用let/const的提升（有"暂时性死区"）
// console.log(hoistedLet); // 错误: Cannot access 'hoistedLet' before initialization
let hoistedLet = "我也被提升了，但不能在声明前访问";

// 函数声明的提升（完整提升）
sayHello(); // 正常工作，输出: "你好！"
function sayHello() {
  console.log("你好！");
}

// 函数表达式不会被完整提升
// sayHi(); // 错误: sayHi is not a function
var sayHi = function() {
  console.log("嗨！");
};
```

理解变量提升有助于避免一些难以追踪的bug，特别是在使用`var`声明变量时。

### 暂时性死区：不能太心急

暂时性死区（Temporal Dead Zone, TDZ）是ES6引入的概念，它指的是变量在声明之前存在但不能被访问的区域。

```javascript
{
  // 从这里开始到let声明之前，myVar处于暂时性死区中
  // console.log(myVar); // 错误: Cannot access 'myVar' before initialization

  let myVar = "现在可以使用了";
  console.log(myVar); // 正常工作
}
```

暂时性死区帮助我们捕获变量在声明前意外使用的错误，增强了代码的可靠性。

### 垃圾回收：告别不再需要的记忆

JavaScript的垃圾回收器会自动管理内存，当变量不再有任何引用时，它会被清理掉：

```javascript
function createObject() {
  let obj = { name: "临时对象" };
  return obj;
}

let reference = createObject(); // obj现在有一个外部引用
reference = null; // 移除引用，对象可以被垃圾回收
```

通常你不需要手动管理内存，但了解垃圾回收的工作原理有助于写出更高效的代码并避免内存泄漏。

## 闭包基础：神奇的记忆能力

闭包是JavaScript中最强大也最容易让人困惑的特性之一。简单来说，闭包就是一个函数和它所在的词法环境的组合，这使得函数可以"记住"并访问它被创建时的作用域，即使该函数在外部被调用。

### 闭包概念：函数的"记忆力"

想象一下，闭包就像是一个带着"记忆背包"的函数，无论这个函数走到哪里，它都能记住并访问它的"出生地"的变量。

```javascript
function createGreeter(name) {
  // name是外部变量

  // 返回一个新函数，这个函数形成了一个闭包
  return function() {
    // 即使在createGreeter执行完后，内部函数仍能访问name
    console.log(`你好，${name}！`);
  };
}

const greetZhangSan = createGreeter("张三");
const greetLiSi = createGreeter("李四");

// 即使createGreeter已经执行完毕，但返回的函数仍然"记得"name的值
greetZhangSan(); // 输出: "你好，张三！"
greetLiSi(); // 输出: "你好，李四！"
```

这个例子中，即使`createGreeter`函数已经执行完毕，但返回的函数仍然可以访问`name`参数。这就是闭包的魔力 - 它让函数保持对其创建环境中变量的引用。

### 闭包形成：捕获变量的过程

闭包的形成非常简单：当一个函数在另一个函数内部定义，并且内部函数引用了外部函数的变量，闭包就形成了。

```javascript
function outer() {
  let counter = 0; // 外部变量

  // 内部函数形成闭包，"捕获"了counter变量
  function incrementCounter() {
    counter++; // 访问外部函数的变量
    console.log(counter);
  }

  return incrementCounter; // 返回内部函数
}

const increment = outer(); // 获取内部函数
increment(); // 输出: 1
increment(); // 输出: 2
increment(); // 输出: 3
```

这个例子中，`incrementCounter`函数捕获了`outer`函数中的`counter`变量，使其在`outer`函数执行完毕后仍然存活，并且状态得到了保持。

### 闭包特性：持久的状态

闭包的一个关键特性是它可以创建持久的、私有的状态：

```javascript
function createCounter() {
  let count = 0; // 私有变量，外部无法直接访问

  return {
    increment: function() {
      count++;
      return count;
    },
    decrement: function() {
      count--;
      return count;
    },
    getCount: function() {
      return count;
    }
  };
}

const counter = createCounter();
console.log(counter.increment()); // 1
console.log(counter.increment()); // 2
console.log(counter.decrement()); // 1
console.log(counter.getCount()); // 1

// 无法直接访问或修改count变量
// counter.count = 100; // 无效
// console.log(counter.count); // undefined
```

在这个例子中，`count`变量对外部代码是完全隐藏的，只能通过返回的方法间接操作，这实现了真正的封装。

### 内存管理：闭包的代价

闭包虽然强大，但使用不当可能导致内存泄漏，因为它会阻止被捕获变量的回收：

```javascript
function createHeavyObject() {
  // 假设这是一个占用大量内存的对象
  const heavyData = new Array(10000).fill('大数据');

  return function() {
    // 使用了heavyData，因此它被保留在内存中
    console.log(heavyData.length);
  };
}

const leakingFunction = createHeavyObject(); // heavyData现在被引用在闭包中
// 即使你不再调用leakingFunction，heavyData也会占用内存

// 正确的做法是在不需要时解除引用
// leakingFunction = null; // 允许垃圾回收器回收内存
```

在使用闭包时，记得在不再需要时解除对闭包的引用，以便垃圾回收器能够回收内存。

## 闭包应用：实战技巧

闭包不只是一个理论概念，它在实际开发中有许多强大的应用场景。

### 数据私有化：创建安全的封装

闭包让我们能够创建私有变量和方法，实现真正的封装：

```javascript
function createBankAccount(initialBalance) {
  let balance = initialBalance; // 私有变量

  // 私有函数
  function validateAmount(amount) {
    return amount > 0 && amount <= balance;
  }

return {
    deposit: function(amount) {
      if (amount > 0) {
        balance += amount;
        return `存款成功，当前余额: ¥${balance}`;
      }
      return "存款金额必须大于0";
    },
    withdraw: function(amount) {
      if (validateAmount(amount)) {
        balance -= amount;
        return `取款成功，当前余额: ¥${balance}`;
      }
      return "取款金额无效或余额不足";
    },
    getBalance: function() {
      return `当前余额: ¥${balance}`;
    }
  };
}

const myAccount = createBankAccount(1000);
console.log(myAccount.getBalance()); // "当前余额: ¥1000"
console.log(myAccount.withdraw(500)); // "取款成功，当前余额: ¥500"
console.log(myAccount.deposit(200)); // "存款成功，当前余额: ¥700"
// 无法直接访问或修改balance
// console.log(myAccount.balance); // undefined
```

这个银行账户示例展示了闭包如何保护数据并提供受控的访问接口。

### 函数工厂：批量定制函数

闭包可以帮助我们创建定制化的函数：

```javascript
// 税率计算器工厂
function createTaxCalculator(taxRate) {
  // 返回特定税率的计算器函数
  return function(amount) {
    return amount * (1 + taxRate);
  };
}

// 创建不同地区的税率计算器
const calculateWithBeijingTax = createTaxCalculator(0.06); // 北京增值税率6%
const calculateWithShanghaiTax = createTaxCalculator(0.065); // 上海增值税率6.5%

// 使用特定税率计算
console.log(calculateWithBeijingTax(100)); // 106
console.log(calculateWithShanghaiTax(100)); // 106.5
```

函数工厂模式让我们能够根据不同参数创建一系列相关但独特的函数。

### 模块化：组织和封装代码

闭包是JavaScript模块模式的基础，它允许我们创建有私有状态和方法的模块：

```javascript
// 简单的购物车模块
const shoppingCart = (function() {
  // 私有变量
  const items = [];

  // 私有函数
  function calculateTotal() {
    return items.reduce((total, item) => total + item.price * item.quantity, 0);
  }

// 公开的API
  return {
    addItem: function(name, price, quantity = 1) {
      items.push({ name, price, quantity });
      console.log(`已添加: ${name}`);
    },
    removeItem: function(name) {
      const index = items.findIndex(item => item.name === name);
      if (index !== -1) {
        items.splice(index, 1);
        console.log(`已移除: ${name}`);
      }
    },
    getItemCount: function() {
      return items.length;
    },
    getTotal: function() {
      return calculateTotal();
    },
    listItems: function() {
      return items.map(item => `${item.name}: ¥${item.price} x ${item.quantity}`);
    }
  };
})(); // 立即执行函数

// 使用购物车模块
shoppingCart.addItem("键盘", 299, 1);
shoppingCart.addItem("鼠标", 99, 2);
console.log(`购物车中有${shoppingCart.getItemCount()}件商品`);
console.log(`总价: ¥${shoppingCart.getTotal()}`);
console.log(shoppingCart.listItems());
```

这个购物车模块使用了立即执行函数表达式（IIFE）和闭包来创建一个有私有状态的模块，同时只暴露必要的接口。

### 性能优化：记忆化与缓存

闭包可以用于实现记忆化（memoization），缓存函数结果以提高性能：

```javascript
// 使用闭包实现记忆化的斐波那契数列计算
function createFibonacciCalculator() {
  // 缓存计算结果
  const cache = {};

  function fibonacci(n) {
    // 检查缓存中是否已有结果
    if (n in cache) {
      console.log(`使用缓存结果: fib(${n})`);
      return cache[n];
    }

    console.log(`计算: fib(${n})`);
    // 计算结果并缓存
    let result;
    if (n <= 1) {
      result = n;
    } else {
      result = fibonacci(n - 1) + fibonacci(n - 2);
    }

    cache[n] = result;
    return result;
  }

  return fibonacci;
}

const fib = createFibonacciCalculator();
console.log(fib(6)); // 计算所有需要的值
console.log(fib(6)); // 使用缓存结果
```

记忆化是一种以空间换时间的优化技术，非常适合计算量大但输入有限的函数。

## 常见错误与注意事项

### 1. 循环中创建闭包

在循环中创建闭包时，引用的变量可能不是你期望的值：

```javascript
// 错误示例
function createButtons() {
  for (var i = 0; i < 3; i++) {
    var button = document.createElement('button');
    button.textContent = `按钮 ${i}`;
    button.onclick = function() {
      console.log(`点击了按钮 ${i}`); // 总是输出"点击了按钮 3"
    };
    document.body.appendChild(button);
  }
}

// 正确示例 - 使用let创建块级作用域
function createButtonsCorrectly() {
  for (let i = 0; i < 3; i++) { // 使用let而不是var
    const button = document.createElement('button');
    button.textContent = `按钮 ${i}`;
    button.onclick = function() {
      console.log(`点击了按钮 ${i}`); // 正确捕获每次迭代的i值
    };
    document.body.appendChild(button);
  }
}
```

### 2. 过度使用闭包导致内存问题

```javascript
// 潜在的内存问题
function addHandler() {
  const largeData = new Array(10000).fill('数据');

  document.getElementById('myButton').addEventListener('click', function() {
    // 这个事件处理函数形成闭包，引用了largeData
    console.log(largeData.length);
  });
}

// 更好的做法 - 只保留需要的数据
function addHandlerBetter() {
  const dataSize = prepareData(); // 假设这个函数返回数据大小

  document.getElementById('myButton').addEventListener('click', function() {
    // 只捕获必要的信息
    console.log(`数据大小: ${dataSize}`);
  });

  // 数据处理完毕，可以被垃圾回收
  function prepareData() {
    const largeData = new Array(10000).fill('数据');
    return largeData.length;
  }
}
```

### 3. this关键字在闭包中的行为

```javascript
// 错误示例
const user = {
  name: "张三",
  greet: function() {
    setTimeout(function() {
      console.log(`你好，${this.name}`); // 输出: "你好，undefined"
    }, 1000);
  }
};

// 正确示例 - 使用箭头函数
const userCorrect = {
  name: "张三",
  greet: function() {
    setTimeout(() => {
      console.log(`你好，${this.name}`); // 输出: "你好，张三"
    }, 1000);
  }
};

// 另一个正确示例 - 保存this引用
const userAlsoCorrect = {
  name: "张三",
  greet: function() {
    const self = this;
    setTimeout(function() {
      console.log(`你好，${self.name}`); // 输出: "你好，张三"
    }, 1000);
  }
};
```

## 总结

作用域和闭包是JavaScript中最基础也最强大的概念，掌握它们将极大地提升你的编程能力。作用域让我们能够组织和控制变量的可见性，而闭包则让函数拥有了"记忆"的能力，能够保持对其创建环境的引用。

通过这些概念，我们可以实现数据隐藏、状态管理、模块化和性能优化等多种高级编程技术。无论是在原生JavaScript中，还是在React、Vue等现代前端框架中，作用域和闭包的应用无处不在。

随着你编程经验的增长，你会发现自己越来越频繁地使用这些概念，它们将成为你解决复杂问题的得力工具。记住，理解概念只是第一步，真正的掌握来自于实践和应用。

## 拓展阅读

### Boolean（布尔值）
```javascript
let isLoggedIn = true;
let hasError = false;
```
布尔值只有两个可能的值：`true`（真）或`false`（假）。它们通常用于条件判断和逻辑操作。

### Object（对象）
```javascript
let person = {
  name: "小红",
  age: 22,
  greeting: function() {
    console.log("你好！");
  }
};

console.log(person.name);  // 输出: 小红
person.greeting();         // 输出: 你好！
```
对象是键值对的集合，可以存储数据和函数（方法）。它是JavaScript中最重要的数据类型之一，几乎所有其他复杂类型都基于对象。

### Function（函数）
```javascript
function sayHello(name) {
  return `你好，${name}！`;
}

console.log(sayHello("小明"));  // 输出: 你好，小明！
```
函数是可以被调用执行的代码块。在JavaScript中，函数也是一种特殊的对象，可以像其他值一样传递和操作。

### var
```javascript
var message = "旧版变量声明";
var count = 10;
```
`var`是最早的变量声明方式。它的作用域是函数级的，可以被重复声明，也存在变量提升。

### let
```javascript
let message = "新版变量声明";
let count = 10;
```
ES6引入的`let`声明，作用域是块级的（花括号内），不能在同一作用域中重复声明，也不会像`var`那样提升。

### const
```javascript
const PI = 3.14159;
const API_URL = "https://api.example.com";
```
`const`声明常量，一旦赋值就不能改变。但如果值是对象，对象的属性仍然可以修改。

### 变量提升
```javascript
console.log(message);  // 输出: undefined
var message = "你好";

// 等同于：
var message;
console.log(message);
message = "你好";
```
使用`var`声明的变量会在代码执行前被"提升"到当前作用域的顶部，但只有声明提升，赋值不会提升。

### 显式转换
```javascript
// 转为字符串
let num = 123;
let str = String(num);  // "123"

// 转为数字
let str2 = "456";
let num2 = Number(str2);  // 456

// 转为布尔值
let empty = "";
let bool = Boolean(empty);  // false，空字符串转为false
```
使用内置函数如`String()`、`Number()`和`Boolean()`可以明确地进行类型转换。

#### CommonJS
这是Node.js中使用的模块系统，使用`require()`导入，`module.exports`导出。

```javascript
// 导出模块
module.exports = {
  sayHello: function() {
    console.log('你好，世界！');
  }
};

// 导入模块
const myModule = require('./myModule');
myModule.sayHello(); // 输出：你好，世界！
```

**特点**：同步加载，简单易用，但不适合浏览器环境（需要打包工具转换）。

#### ES Modules
现代JavaScript的官方模块系统，使用`import`和`export`语法。

```javascript
// 导出模块 (helper.js)
export function sayHello() {
  console.log('你好，世界！');
}

// 导入模块 (app.js)
import { sayHello } from './helper.js';
sayHello(); // 输出：你好，世界！
```

**特点**：静态导入导出，可以进行树摇（移除未使用的代码），现代浏览器原生支持。

### Webpack：全能型选手
Webpack是目前最流行的前端构建工具之一，就像一个强大的食品加工厂，可以处理几乎所有类型的"食材"（文件）。

```javascript
// webpack.config.js 基础配置示例
module.exports = {
  entry: './src/index.js',    // 入口：你的主文件在哪里
  output: {                   // 出口：加工后的文件放在哪里
    path: path.resolve(__dirname, 'dist'),
    filename: 'bundle.js'
  },
  module: {                   // 模块：如何处理不同类型的文件
    rules: [
      {
        test: /\.css$/,       // 处理CSS文件的规则
        use: ['style-loader', 'css-loader']
      }
    ]
  }
};
```

**优点**：
- 功能全面，生态丰富
- 高度可配置，适应复杂项目需求
- 社区活跃，问题容易找到解决方案

**缺点**：
- 配置复杂，学习曲线陡峭
- 构建速度较慢（尤其是大型项目）

### Rollup：库开发之选
Rollup更适合于打包JavaScript库，它就像是一个精致的糕点作坊，专注于制作精美小巧的点心。

```javascript
// rollup.config.js 基础配置示例
export default {
  input: 'src/main.js',            // 入口文件
  output: {
    file: 'bundle.js',             // 输出文件
    format: 'cjs'                  // 输出格式（CommonJS）
  }
};
```

**优点**：
- 生成更干净、更小的代码
- 对ES模块有优秀的支持
- 树摇效果很好

**缺点**：
- 处理非JS资源需要插件
- 不太适合复杂的应用开发

### 2. 模块解析路径问题
问题：找不到模块，通常是路径配置错误。
解决：检查import路径，确保路径正确。可以使用别名（alias）简化路径。

```javascript
