### 什么是中间件？

中间件（Middleware）是一个函数，它可以访问请求对象（request）、响应对象（response）以及应用程序请求-响应周期中的下一个函数（通常用变量`next`表示）。简单来说，中间件就是在请求到达最终处理程序之前执行的一系列处理函数。

在Express等框架中，中间件函数通常具有以下形式：

```javascript
function myMiddleware(req, res, next) {
  // 1. 可以访问请求对象 req
  // 2. 可以访问响应对象 res
  // 3. 执行任何操作（如修改请求/响应对象）

  // 4. 调用下一个中间件
  next();

  // 或者结束请求-响应周期
  // res.send('响应内容');
}
```

### 1. 应用级中间件

应用级中间件绑定到Express `app`实例，使用`app.use()`或`app.METHOD()`（如`app.get()`、`app.post()`等）方法：

```javascript
const express = require('express');
const app = express();

// 应用级中间件，适用于所有请求
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

// 应用级中间件，仅适用于特定路径
app.use('/api', (req, res, next) => {
  console.log('API路径被访问');
  next();
});

// 应用级中间件，仅适用于特定HTTP方法和路径
app.get('/users', (req, res, next) => {
  console.log('获取用户列表');
  next();
});
```

这类中间件适合实现日志记录、身份验证、请求解析等全局性功能。

### 2. 路由级中间件

路由级中间件与应用级中间件工作方式相同，但它绑定到`express.Router()`实例：

```javascript
const express = require('express');
const router = express.Router();

// 路由级中间件
router.use((req, res, next) => {
  console.log('用户路由中间件');
  next();
});

router.get('/', (req, res) => {
  res.send('用户列表');
});

router.get('/:id', (req, res) => {
  res.send(`用户ID: ${req.params.id}`);
});

module.exports = router;

// 在主应用中使用路由
// app.use('/users', userRouter);
```

路由级中间件允许我们将相关的路由和中间件组织到独立的模块中，提高代码的可维护性。

### 3. 错误处理中间件

错误处理中间件用于集中处理应用中的错误，它有4个参数（比普通中间件多一个`err`参数）：

```javascript
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('服务器内部错误');
});
```

要使用错误处理中间件，通常有两种方式：
1. 在常规中间件中捕获错误并调用`next(error)`
2. 使用`try/catch`块捕获异步操作中的错误

```javascript
// 方式1：在中间件中主动传递错误
app.use((req, res, next) => {
  if (!req.headers.authorization) {
    // 创建错误对象并传递给下一个中间件
    const error = new Error('未授权');
    error.status = 401;
    return next(error);
  }
  next();
});

// 方式2：使用try/catch捕获异步错误
app.get('/users/:id', async (req, res, next) => {
  try {
    const user = await User.findById(req.params.id);
    if (!user) {
      // 如果用户不存在，创建404错误
      const error = new Error('用户不存在');
      error.status = 404;
      throw error;
    }
    res.json(user);
  } catch (err) {
    // 将捕获的错误传递给错误处理中间件
    next(err);
  }
});

// 错误处理中间件（应该定义在所有其他中间件之后）
app.use((err, req, res, next) => {
  // 设置状态码（默认为500）
  res.status(err.status || 500);

  // 返回错误响应
  res.json({
    error: {
      message: err.message,
      // 在开发环境中返回堆栈信息
      ...(process.env.NODE_ENV === 'development' ? { stack: err.stack } : {})
    }
  });
});
```

错误处理中间件应该定义在最后，以捕获整个应用中的错误。

### 4. 内置中间件

Express框架提供了一些内置中间件，用于常见任务：

```javascript
// 解析JSON请求体
app.use(express.json());

// 解析URL编码的请求体
app.use(express.urlencoded({ extended: true }));

// 提供静态文件
app.use(express.static('public'));
```

这些内置中间件使得常见的Web应用任务变得简单。

### 5. 第三方中间件

Node.js生态系统中有大量优秀的第三方中间件，用于各种功能：

```javascript
// 处理CORS（跨域资源共享）
const cors = require('cors');
app.use(cors());

// 记录HTTP请求日志
const morgan = require('morgan');
app.use(morgan('dev'));

// 增强安全性
const helmet = require('helmet');
app.use(helmet());

// 解析Cookie
const cookieParser = require('cookie-parser');
app.use(cookieParser());

// 会话管理
const session = require('express-session');
app.use(session({
  secret: 'mySecretKey',
  resave: false,
  saveUninitialized: true,
  cookie: { secure: true }
}));

// 文件上传
const multer = require('multer');
const upload = multer({ dest: 'uploads/' });
app.post('/upload', upload.single('file'), (req, res) => {
  res.send('文件上传成功');
});
```

这些中间件大大扩展了应用的功能，同时保持代码的简洁性。

### 基本的中间件结构

自定义中间件的基本结构如下：

```javascript
function myCustomMiddleware(options = {}) {
  // 1. 中间件配置和初始化
  const { optionA = 'defaultValueA', optionB = 'defaultValueB' } = options;

  // 2. 返回实际的中间件函数
  return function(req, res, next) {
    // 3. 中间件逻辑
    try {
      // 执行某些操作...

      // 4. 调用下一个中间件
      next();
    } catch (error) {
      // 5. 错误处理
      next(error);
    }
  };
}
```

#### 1. 请求记录中间件

```javascript
// 记录请求信息的中间件
function requestLogger(options = {}) {
  const { logLevel = 'info' } = options;

  return (req, res, next) => {
    const startTime = Date.now();

    console.log(`[${logLevel.toUpperCase()}] ${req.method} ${req.url} - 开始请求`);

    // 在响应对象上重写end方法，以便计算请求处理时间
    const originalEnd = res.end;
    res.end = function(...args) {
      const duration = Date.now() - startTime;
      console.log(`[${logLevel.toUpperCase()}] ${req.method} ${req.url} - ${res.statusCode} - ${duration}ms`);
      originalEnd.apply(res, args);
    };

    next();
  };
}

// 使用自定义中间件
app.use(requestLogger({ logLevel: 'debug' }));
```

#### 2. 简单的认证中间件

```javascript
// 基于令牌的认证中间件
function authenticate(options = {}) {
  const { tokenSecret = 'defaultSecret', excludePaths = [] } = options;

  return (req, res, next) => {
    // 检查是否为排除路径
    if (excludePaths.some(path => req.path.startsWith(path))) {
      return next();
    }

    // 获取授权头
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ message: '未提供认证令牌' });
    }

    // 提取令牌
    const token = authHeader.substring(7);

    try {
      // 验证令牌（此处使用jwt库示例）
      const decoded = jwt.verify(token, tokenSecret);
      req.user = decoded; // 将解码后的用户信息添加到请求对象
      next();
    } catch (error) {
      res.status(401).json({ message: '无效的认证令牌' });
    }
  };
}

// 使用自定义认证中间件
app.use(authenticate({
  tokenSecret: process.env.JWT_SECRET,
  excludePaths: ['/auth/login', '/auth/register', '/public']
}));
```

#### 3. 请求速率限制中间件

```javascript
// 简易速率限制中间件
function rateLimit(options = {}) {
  const {
    windowMs = 60 * 1000, // 默认窗口期为1分钟
    maxRequests = 100,    // 默认每个窗口期最多100个请求
    message = '请求过多，请稍后再试'
  } = options;

  // 使用内存存储请求记录（生产环境应使用Redis等分布式存储）
  const requestRecords = {};

  // 定期清理过期的记录
  setInterval(() => {
    const now = Date.now();
    for (const ip in requestRecords) {
      if (now - requestRecords[ip].timestamp > windowMs) {
        delete requestRecords[ip];
      }
    }
  }, windowMs);

  return (req, res, next) => {
    // 获取客户端IP
    const ip = req.ip || req.connection.remoteAddress;
    const now = Date.now();

    // 初始化或更新请求记录
    if (!requestRecords[ip] || now - requestRecords[ip].timestamp > windowMs) {
      requestRecords[ip] = {
        count: 1,
        timestamp: now
      };
    } else {
      requestRecords[ip].count++;
    }

    // 检查是否超过限制
    if (requestRecords[ip].count > maxRequests) {
      return res.status(429).json({ message });
    }

next();
  };
}

// 使用速率限制中间件
app.use(rateLimit({
  windowMs: 15 * 60 * 1000, // 15分钟
  maxRequests: 100           // 每15分钟100个请求
}));

// 对特定路由应用更严格的限制
app.use('/api/login', rateLimit({
  windowMs: 60 * 60 * 1000,  // 1小时
  maxRequests: 5             // 每小时5次登录尝试
}));
```

### 1. 正确的中间件顺序

中间件的执行顺序很重要。一般来说：

1. 先加载处理所有请求的通用中间件（日志、安全相关等）
2. 然后是请求体解析、会话管理等中间件
3. 接着是应用特定的中间件（如认证、授权）
4. 最后是路由处理和404处理
5. 错误处理中间件应该放在最后

```javascript
// 示例中间件顺序
app.use(helmet());                        // 安全头设置
app.use(morgan('dev'));                   // 请求日志
app.use(express.json());                  // 请求体解析
app.use(express.urlencoded({ extended: true }));
app.use(cookieParser());                  // Cookie解析
app.use(session({ /* 配置 */ }));        // 会话管理

app.use(authenticate());                  // 身份认证

app.use('/api/users', userRoutes);        // 路由
app.use('/api/products', productRoutes);

// 404处理
app.use((req, res, next) => {
  res.status(404).json({ message: '找不到请求的资源' });
});

// 错误处理中间件（始终放在最后）
app.use((err, req, res, next) => {
  res.status(err.status || 500).json({ message: err.message });
});
```

### 2. 避免异步陷阱

在异步中间件中，一定要正确处理异步操作并调用`next()`：

```javascript
// ❌ 错误示例：没有正确处理异步操作
app.use((req, res, next) => {
  fs.readFile('/path/to/file', (err, data) => {
    if (err) {
      return next(err);
    }
    req.fileData = data;
    next();
  });
  // 这里会立即执行，而不等待文件读取完成！
});

// ✅ 正确示例：等待异步操作完成再调用next()
app.use((req, res, next) => {
  fs.readFile('/path/to/file', (err, data) => {
    if (err) {
      return next(err);
    }
    req.fileData = data;
    next();
  });
  // 不在这里调用next()
});

// ✅ 使用async/await更简洁地处理异步操作
app.use(async (req, res, next) => {
  try {
    const data = await fs.promises.readFile('/path/to/file');
    req.fileData = data;
    next();
  } catch (err) {
    next(err);
  }
});
```

### 3. 避免在中间件中不调用next()或不结束响应

每个中间件必须调用`next()`或结束响应（如`res.send()`、`res.end()`等），否则请求会挂起：

```javascript
// ❌ 错误示例：请求会挂起
app.use((req, res, next) => {
  if (req.path === '/admin') {
    if (!req.user.isAdmin) {
      res.status(403).send('禁止访问');
      // 这里缺少return，会继续执行下面的next()
    }
  }
  next();
});

// ✅ 正确示例：使用return确保只有一个出口点
app.use((req, res, next) => {
  if (req.path === '/admin') {
    if (!req.user.isAdmin) {
      return res.status(403).send('禁止访问');
    }
  }
  next();
});
```

### 4. 中间件组合与复用

将中间件组合成可复用的单元，避免代码重复：

```javascript
// 认证和授权中间件组合
function adminOnly(options = {}) {
  return [
    authenticate(options),
    (req, res, next) => {
      if (!req.user || !req.user.isAdmin) {
        return res.status(403).json({ message: '需要管理员权限' });
      }
      next();
    }
  ];
}

// 使用组合中间件
app.get('/admin/dashboard', adminOnly(), (req, res) => {
  res.send('管理员仪表盘');
});
```

### 5. 性能考虑

中间件会影响应用性能，应注意以下几点：

- 避免在中间件中执行耗时操作，必要时使用缓存
- 不是所有路由都需要所有中间件，使用条件应用
- 中间件按需加载，不要为所有请求加载不必要的中间件

```javascript
// 条件应用中间件示例
app.use((req, res, next) => {
  // 仅为API请求解析JSON
  if (req.path.startsWith('/api')) {
    express.json()(req, res, next);
  } else {
    next();
  }
});
```

### 1. 洋葱模型（Onion Model）

中间件的执行顺序形成一个"洋葱"结构：请求从外到内穿过所有中间件层，响应则从内到外返回：

```
请求 → 中间件1开始 → 中间件2开始 → 路由处理 → 中间件2结束 → 中间件1结束 → 响应
```

这种模式在Koa框架中尤为明显，但在Express中也可以实现：

```javascript
app.use((req, res, next) => {
  console.log('中间件1：开始');

  // 调用下一个中间件
  next();

  // 这部分代码会在响应返回时执行
  console.log('中间件1：结束');
});

app.use((req, res, next) => {
  console.log('中间件2：开始');
  next();
  console.log('中间件2：结束');
});

app.get('/', (req, res) => {
  console.log('路由处理');
  res.send('Hello World');
});
```

### 2. 责任链模式（Chain of Responsibility）

中间件形成一个责任链，每个处理器决定是否处理请求或传递给下一个：

```javascript
// 基于角色的授权中间件
function authorize(role) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ message: '未认证' });
    }

    if (req.user.role === role || req.user.role === 'admin') {
      return next(); // 有权限，传递给下一个处理器
    }

    res.status(403).json({ message: '权限不足' });
  };
}

// 使用责任链模式
app.get('/api/reports', authenticate(), authorize('manager'), (req, res) => {
  res.json({ reports: [] });
});
```

### 3. 管道和过滤器（Pipes and Filters）

请求通过一系列"过滤器"（中间件），每个过滤器执行特定的转换或处理：

```javascript
// 过滤器：格式化查询参数
function formatQueryParams(req, res, next) {
  if (req.query.page) {
    req.query.page = parseInt(req.query.page, 10);
  }
  if (req.query.limit) {
    req.query.limit = parseInt(req.query.limit, 10);
  }
  next();
}

// 过滤器：分页处理
function paginate(req, res, next) {
  const page = req.query.page || 1;
  const limit = req.query.limit || 10;
  req.pagination = {
    skip: (page - 1) * limit,
    limit: limit
  };
  next();
}

// 管道：应用多个过滤器
app.get('/api/users', formatQueryParams, paginate, async (req, res) => {
  const users = await User.find()
    .skip(req.pagination.skip)
    .limit(req.pagination.limit);
  res.json(users);
});
```

### 导出模块：module.exports与exports

在CommonJS中，我们可以通过`module.exports`或`exports`对象来导出模块内容：

```javascript
// 方式1：使用module.exports导出单个对象
module.exports = {
  add: function(a, b) {
    return a + b;
  },
  subtract: function(a, b) {
    return a - b;
  }
};

// 方式2：直接导出函数
module.exports = function(a, b) {
  return a + b;
};

// 方式3：使用exports对象添加多个导出项
exports.add = function(a, b) {
  return a + b;
};

exports.subtract = function(a, b) {
  return a - b;
};
```

**注意事项：** `exports`是`module.exports`的引用，直接替换`exports`会切断这种引用关系。因此，不能这样写：

```javascript
// ❌ 错误写法：这会切断exports与module.exports的引用关系
exports = {
  add: function(a, b) {
    return a + b;
  }
};
// 此时外部依然无法访问add函数
```

正确的做法是，要么使用`module.exports`直接赋值，要么给`exports`的属性赋值：

```javascript
// ✅ 正确写法1：
module.exports = {
  add: function(a, b) {
    return a + b;
  }
};

// ✅ 正确写法2：
exports.add = function(a, b) {
  return a + b;
};
```

### 导入模块：require函数

在CommonJS中，我们使用`require()`函数来导入模块：

```javascript
// 导入核心模块
const fs = require('fs');
const path = require('path');

// 导入本地模块（./ 或 ../ 开头的路径）
const myModule = require('./myModule');
const config = require('../config');

// 导入npm安装的模块
const express = require('express');
const axios = require('axios');
```

`require()`函数的寻找模块的规则如下：

1. 如果是核心模块（如`fs`、`path`等），直接返回内置模块
2. 如果路径以`./`或`../`开头，则尝试按照文件路径查找
   - 首先查找确切的文件名
   - 然后尝试添加.js、.json、.node扩展名
   - 最后查找同名目录下的index.js、index.json或index.node
3. 如果不是路径也不是核心模块，则在node_modules目录中查找

### 模块缓存机制

Node.js会缓存已加载的模块，这意味着无论一个模块被`require`多少次，它只会在第一次加载时执行，之后都返回缓存结果：

```javascript
// moduleA.js
console.log('moduleA被加载了！');
module.exports = { name: 'moduleA' };

// app.js
const moduleA1 = require('./moduleA'); // 输出：moduleA被加载了！
const moduleA2 = require('./moduleA'); // 没有输出，使用缓存

console.log(moduleA1 === moduleA2); // 输出：true
```

如果需要每次都获取新实例，可以导出一个工厂函数：

```javascript
// moduleB.js
module.exports = function() {
  return {
    name: 'moduleB',
    createdAt: new Date()
  };
};

// app.js
const createModuleB = require('./moduleB');
const instance1 = createModuleB();
const instance2 = createModuleB();

console.log(instance1 === instance2); // 输出：false
```

### 模块的循环依赖

当两个模块相互引用对方时，会产生循环依赖。Node.js通过返回"未完成"的模块来解决这个问题：

```javascript
// a.js
console.log('a.js开始加载');
const b = require('./b');
console.log('在a.js中，b.done =', b.done);
module.exports = { done: true };
console.log('a.js结束加载');

// b.js
console.log('b.js开始加载');
const a = require('./a');
console.log('在b.js中，a.done =', a.done);
module.exports = { done: true };
console.log('b.js结束加载');

// main.js
console.log('main.js开始加载');
const a = require('./a');
console.log('在main.js中，a.done =', a.done);
```

执行`node main.js`的输出：

```
main.js开始加载
a.js开始加载
b.js开始加载
在b.js中，a.done = undefined
b.js结束加载
在a.js中，b.done = true
a.js结束加载
在main.js中，a.done = true
```

注意：循环依赖通常是设计问题的征兆，应尽量避免。

### 导出模块：export关键字

ESM使用`export`关键字导出模块内容：

```javascript
// 命名导出
export function add(a, b) {
  return a + b;
}

export function subtract(a, b) {
  return a - b;
}

// 或者集中导出
function multiply(a, b) {
  return a * b;
}

function divide(a, b) {
  return a / b;
}

export { multiply, divide };

// 导出时重命名
export { multiply as mul, divide as div };

// 默认导出
export default function(a, b) {
  return a + b;
}
```

与CommonJS不同，ESM支持"默认导出"和"命名导出"两种方式，并且可以在同一个模块中同时使用。

### 导入模块：import关键字

ESM使用`import`关键字导入模块：

```javascript
// 导入默认导出
import add from './math.js';

// 导入命名导出
import { subtract, multiply } from './math.js';

// 导入时重命名
import { subtract as sub, multiply as mul } from './math.js';

// 导入所有命名导出
import * as math from './math.js';

// 同时导入默认导出和命名导出
import add, { subtract, multiply } from './math.js';

// 动态导入（返回Promise）
import('./math.js')
  .then(math => {
    console.log(math.add(1, 2));
  })
  .catch(err => {
    console.error('模块加载失败', err);
  });

// 使用await动态导入（在async函数内）
async function loadMath() {
  const math = await import('./math.js');
  return math.add(1, 2);
}
```

#### 实时绑定示例

```javascript
// counter.js (ESM)
export let count = 0;
export function increment() {
  count++;
}

// app.js (ESM)
import { count, increment } from './counter.js';
console.log(count); // 输出：0
increment();
console.log(count); // 输出：1，因为导入的是绑定，而不是值的拷贝
```

如果使用CommonJS，结果会不同：

```javascript
// counter.js (CommonJS)
let count = 0;
function increment() {
  count++;
}
module.exports = { count, increment };

// app.js (CommonJS)
const { count, increment } = require('./counter');
console.log(count); // 输出：0
increment();
console.log(count); // 输出：0，因为导入的是值的拷贝
```

### 在ESM中导入CommonJS模块

ESM可以导入CommonJS模块，遵循以下规则：

1. CommonJS的`module.exports`会被视为默认导出
2. 如果`module.exports`是对象，其属性也会作为命名导出提供

```javascript
// math.cjs (CommonJS)
module.exports = {
  add: (a, b) => a + b,
  subtract: (a, b) => a - b
};

// app.mjs (ESM)
// 作为默认导出导入
import math from './math.cjs';
console.log(math.add(1, 2)); // 输出：3

// 或作为命名导出导入
import { add, subtract } from './math.cjs';
console.log(add(1, 2)); // 输出：3
```

### 在CommonJS中导入ESM模块

CommonJS不能直接同步导入ESM模块，因为ESM是异步加载的。需要使用动态导入：

```javascript
// math.mjs (ESM)
export function add(a, b) {
  return a + b;
}

export function subtract(a, b) {
  return a - b;
}

// app.cjs (CommonJS)
// ❌ 不能直接使用require
// const math = require('./math.mjs'); // 错误！

// ✅ 使用动态导入
(async () => {
  const math = await import('./math.mjs');
  console.log(math.add(1, 2)); // 输出：3
})();
```

### 子路径导出与导入

Node.js 12.7.0引入了"子路径导出"功能，允许精确控制模块的公共API：

```json
{
  "name": "my-library",
  "exports": {
    ".": "./lib/index.js",
    "./utils": "./lib/utils.js",
    "./utils/*": "./lib/utils/*.js"
  }
}
```

使用时：

```javascript
import myLib from 'my-library';
import { sortBy } from 'my-library/utils';
import { formatDate } from 'my-library/utils/date';
```

这样可以防止用户依赖包的内部结构，使库作者能够在不破坏兼容性的情况下重构代码。

### 使用模块组织技术

1. **桶（Barrel）导出**：使用索引文件整合和重新导出模块

```javascript
// src/utils/index.js - 桶（Barrel）文件
export { default as logger } from './logger.js';
export { default as config } from './config.js';
export * from './helpers.js';

// 使用桶导出
import { logger, config, formatDate } from './utils';
```

2. **动态导入优化**：使用动态导入懒加载大型模块

```javascript
async function processImage(path) {
  // 只在需要时才加载大型库
  const jimp = await import('jimp');
  const image = await jimp.read(path);
  // 处理图片...
  return image;
}
```

### 错误处理与模块加载

```javascript
// 安全地加载可能不存在的模块
let optionalModule;
try {
  optionalModule = require('some-optional-module');
} catch (err) {
  if (err.code !== 'MODULE_NOT_FOUND') {
    throw err; // 重新抛出非模块缺失错误
  }
  // 提供后备实现
  optionalModule = {
    someFunction: () => {
      console.log('使用后备实现');
    }
  };
}
```

### 模块中的环境配置

```javascript
// config.js
const config = {
  development: {
    apiUrl: 'http://localhost:3000/api',
    debug: true
  },
  production: {
    apiUrl: 'https://api.example.com',
    debug: false
  },
  test: {
    apiUrl: 'http://localhost:3001/api',
    debug: true
  }
};

// 使用环境变量选择配置
const env = process.env.NODE_ENV || 'development';
module.exports = config[env];
```

### 局部注册与全局注册

组件定义后，需要注册才能使用。有两种注册方式：

**局部注册**：只在特定父组件中可用

```javascript
// 在父组件中局部注册
export default {
  components: {
    PostCard // 告诉Vue："这个组件会用到PostCard子组件"
  }
}
```

**全局注册**：在整个应用中都可用

```javascript
// main.js中全局注册
const app = createApp(App)
app.component('PostCard', PostCard) // 注册为"PostCard"标签
app.mount('#app')
```

选择建议：
- 大多数组件使用局部注册，避免打包不必要的代码
- 只有真正到处使用的基础组件才用全局注册

### Props 定义与类型校验

Props是父组件向子组件传递数据的方式。想象父组件是老板，子组件是员工 - Props就是老板交给员工的任务和资源。

**简单定义Props**：

```javascript
export default {
  // 简单数组形式
  props: ['title', 'likes', 'isPublished']
}
```

**带类型检查的Props**：

```javascript
export default {
  props: {
    title: String,        // 必须是字符串
    likes: Number,        // 必须是数字
    isPublished: Boolean, // 必须是布尔值
    commentIds: Array,    // 必须是数组
    author: Object        // 必须是对象
  }
}
```

**带完整验证的Props**：
```javascript
export default {
  props: {
    // 基础类型检查
    propA: Number,
    // 多种类型
    propB: [String, Number],
    // 必须传值
    propC: {
      type: String,
      required: true
    },
    // 带默认值
    propD: {
      type: Number,
      default: 100
    },
    // 对象默认值
    propE: {
      type: Object,
      default: function() {
        return { message: 'hello' }
      }
    },
    // 自定义验证函数
    propF: {
      validator: function(value) {
        return ['success', 'warning', 'danger'].includes(value)
      }
    }
  }
}
```

### 单向数据流原则

Vue的Props遵循"单向数据流"原则：父组件可以传数据给子组件，但子组件不能直接修改Props。这是为了防止子组件意外修改父组件的状态，导致数据流向难以理解。

如果需要修改Props数据，应该：

1. **使用本地data存储副本**：
```javascript
export default {
  props: ['initialValue'],
  data() {
    return {
      // 创建一个本地副本
      localValue: this.initialValue
    }
  }
}
```

2. **使用计算属性转换**：
```javascript
export default {
  props: ['size'],
  computed: {
    // 基于props计算新值
    normalizedSize() {
      return this.size.toLowerCase()
    }
  }
}
```

### 子组件向父组件通信：自定义事件

如果说Props是父组件向下传递数据，那么自定义事件就是子组件向上传递信息的方式。

**子组件触发事件**：

```vue

<template>
  <button @click="incrementCounter">点击了 {{ count }} 次</button>
</template>

<script>
export default {
  data() {
    return {
      count: 0
    }
  },
  methods: {
    incrementCounter() {
      this.count++
      // 告诉父组件："按钮被点击了，次数是count"
      this.$emit('increment', this.count)
    }
  }
}
</script>
```

**父组件监听事件**：

```vue

<template>
  <div>
    <p>子组件点击次数: {{ totalClicks }}</p>

    <ButtonCounter @increment="onIncrement"/>
  </div>
</template>

<script>
import ButtonCounter from './ButtonCounter.vue'

export default {
  components: { ButtonCounter },
  data() {
    return {
      totalClicks: 0
    }
  },
  methods: {
    onIncrement(count) {
      this.totalClicks = count
      console.log('子组件被点击了，次数：', count)
    }
  }
}
</script>
```

### 跨级组件通信：Provide/Inject依赖注入

当需要跨多级组件传递数据时，一层层传递props非常麻烦。Vue提供了`provide`和`inject`API来解决这个问题：

```
    祖先组件 (provide提供数据)
       |
     父组件
       |
 后代组件 (inject注入数据)
```

**祖先组件提供数据**：

```vue

<script>
export default {
  provide() {
    return {
      // 提供一个值
      theme: 'dark',
      // 提供一个响应式对象
      user: this.user
    }
  },
  data() {
    return {
      user: { name: '张三' }
    }
  }
}
</script>
```

**后代组件注入数据**：

```vue

<script>
export default {
  inject: ['theme', 'user'],
  created() {
    console.log(this.theme) // 'dark'
    console.log(this.user.name) // '张三'
  }
}
</script>
```

注意：依赖注入会使组件耦合，难以追踪数据来源，所以应谨慎使用，通常只用于组件库或大型应用的特定场景。

### 异步组件：按需加载提升性能

在大型应用中，我们可以把组件拆分成小块，在需要时才加载，这可以提升应用初始加载性能：

```javascript
// Vue3异步组件
import { defineAsyncComponent } from 'vue'

const AsyncComponent = defineAsyncComponent(() =>
  import('./components/HeavyComponent.vue')
)

// 然后在组件中使用
export default {
  components: {
    AsyncComponent
  }
}
```

这样`HeavyComponent`只有在真正使用时才会加载，并且会自动处理加载状态。

### Options API 与 Composition API 对比：两种思维模式

在了解Composition API前，让我们先看看传统的Options API如何组织代码：

```javascript
// Options API 示例
export default {
  // 数据
  data() {
    return {
      user: { name: '张三', age: 30 },
      searchQuery: '',
      searchResults: []
    }
  },
  // 计算属性
  computed: {
    fullName() {
      return this.user.name + '先生/女士'
    }
  },
  // 方法
  methods: {
    updateUser() {
      this.user.age++
    },
    async search() {
      this.searchResults = await api.search(this.searchQuery)
    }
  },
  // 生命周期钩子
  mounted() {
    this.search()
  }
}
```

在Options API中，代码按照选项类型（data/computed/methods等）组织。这对于简单组件很清晰，但随着组件复杂度增加，相关联的代码会分散在不同位置。

而在Composition API中，我们可以按照逻辑功能来组织代码：

```javascript
// Composition API 示例
import { ref, computed, onMounted } from 'vue'

export default {
  setup() {
    // 用户相关逻辑
    const user = ref({ name: '张三', age: 30 })
    const fullName = computed(() => user.value.name + '先生/女士')
    function updateUser() {
      user.value.age++
    }

// 搜索相关逻辑
    const searchQuery = ref('')
    const searchResults = ref([])
    async function search() {
      searchResults.value = await api.search(searchQuery.value)
    }

    // 生命周期
    onMounted(() => {
      search()
    })

    // 返回需要暴露给模板的内容
    return {
      user,
      fullName,
      updateUser,
      searchQuery,
      searchResults,
      search
    }
  }
}
```

**主要优势**：
1. **逻辑关注点分离**：相关逻辑可以集中在一起
2. **更好的代码复用**：可以轻松提取和重用逻辑
3. **更好的TypeScript支持**：提供了更自然的类型推导
4. **减小了打包体积**：通过摇树优化可以移除未使用的导入

### setup 函数：Composition API 的入口

`setup`函数是使用Composition API的入口，它在组件实例创建之前执行，因此无法使用`this`：

```javascript
export default {
  setup(props, context) {
    // props: 组件传入的属性（响应式的）
    console.log(props.title)

    // context: 上下文对象，包含了一些有用的属性
    const { attrs, slots, emit, expose } = context

    // 在这里定义响应式数据、方法、计算属性等

    // 必须返回一个对象，其中的属性将暴露给模板
    return {
      // 这里返回的内容可在模板中使用
    }
  }
}
```

`setup`函数接收两个参数：
- `props`：组件接收的属性，是响应式的，不能使用ES6解构（会失去响应性）
- `context`：上下文对象，包含了`attrs`、`slots`、`emit`和`expose`

// toRefs：解构reactive对象同时保持响应性
const { count, name } = toRefs(state)
count.value++ // 仍然是响应式的

// readonly：创建只读数据
const readonlyState = readonly(state)
// readonlyState.count++ // 这会产生警告

// isRef/isReactive/isReadonly：检查数据类型
console.log(isRef(count)) // true
```

### 生命周期钩子：重命名和使用方式

在Composition API中，生命周期钩子需要从Vue导入，并以`on`开头命名：

```javascript
import {
  onBeforeMount,
  onMounted,
  onBeforeUpdate,
  onUpdated,
  onBeforeUnmount,
  onUnmounted,
  onActivated,
  onDeactivated,
  onErrorCaptured
} from 'vue'

export default {
  setup() {
    // 可以多次调用同一个钩子
    onMounted(() => {
      console.log('组件挂载完成')
    })

    onMounted(() => {
      console.log('这也会在挂载时执行')
    })

    onBeforeUnmount(() => {
      console.log('组件即将卸载')
    })
  }
}
```

注意：没有与`beforeCreate`和`created`对应的组合式API钩子，因为`setup`函数本身就相当于这两个钩子。

### 计算属性与监听器：响应式的衍生状态

**计算属性**：使用`computed`创建

```javascript
import { ref, computed } from 'vue'

export default {
  setup() {
    const firstName = ref('张')
    const lastName = ref('三')

    // 计算属性
    const fullName = computed(() => {
      return firstName.value + lastName.value
    })

    // 可写的计算属性
    const fullName2 = computed({
      get: () => firstName.value + lastName.value,
      set: (newValue) => {
        [firstName.value, lastName.value] = newValue.split(' ')
      }
    })

    return { firstName, lastName, fullName, fullName2 }
  }
}
```

**监听器**：使用`watch`和`watchEffect`

```javascript
import { ref, watch, watchEffect } from 'vue'

export default {
  setup() {
    const count = ref(0)
    const name = ref('张三')

    // watch：指定要监听的数据源
    watch(count, (newValue, oldValue) => {
      console.log(`count从${oldValue}变为${newValue}`)
    })

    // 监听多个数据源
    watch([count, name], ([newCount, newName], [oldCount, oldName]) => {
      console.log('数据变化了')
    })

// watchEffect：自动收集依赖
    watchEffect(() => {
      console.log(`count: ${count.value}, name: ${name.value}`)
      // 这个函数中使用的任何响应式数据变化时，都会重新执行
    })

    return { count, name }
  }
}
```

`watch`与`watchEffect`的区别：
- `watch`需要明确指定监听的数据源
- `watchEffect`会自动追踪函数内使用的所有响应式数据
- `watch`可以访问变化前后的值，而`watchEffect`不行
- `watch`默认是懒执行的，而`watchEffect`在创建时会立即执行一次

### 基本用法：摆脱return语句

使用`<script setup>`后，我们不再需要`setup`函数和返回语句：

```vue
<script setup>
import { ref, computed } from 'vue'

// 直接定义响应式数据
const count = ref(0)
const doubleCount = computed(() => count.value * 2)

// 定义方法
function increment() {
  count.value++
}

// 无需return，所有顶层变量自动暴露给模板
</script>

<template>
  <div>
    <p>Count: {{ count }}</p>
    <p>Double: {{ doubleCount }}</p>
    <button @click="increment">增加</button>
  </div>
</template>
```

所有定义在`<script setup>`中的顶层变量、函数和导入，都会自动暴露给模板，不需要手动返回。

### defineProps 与 defineEmits：组件通信

在`<script setup>`中，我们使用编译宏`defineProps`和`defineEmits`来声明props和emits：

```vue
<script setup>
// 声明props（不需要导入）
const props = defineProps({
  title: String,
  likes: { type: Number, default: 0 },
  isPublished: Boolean,
  author: Object,
  callback: Function,
  contactsPromise: Promise
})

// 使用props
console.log(props.title)

// 声明emits
const emit = defineEmits(['update', 'delete'])

// 调用emit
function handleUpdate() {
  emit('update', { id: 1, text: '新内容' })
}
</script>
```

这些编译宏是由Vue编译器直接处理的，不需要导入。

使用TypeScript时，可以使用类型标注：

```vue
<script setup lang="ts">
// 使用类型声明
const props = defineProps<{
  title: string
  likes?: number
  isPublished: boolean
}>()

const emit = defineEmits<{
  (e: 'update', payload: { id: number, text: string }): void
  (e: 'delete', id: number): void
}>()
</script>
```

### withDefaults：设置默认值

在使用TypeScript类型声明props时，可以使用`withDefaults`设置默认值：

```vue
<script setup lang="ts">
// 定义props类型
interface Props {
  title: string
  likes?: number
  isPublished?: boolean
}

// 设置默认值
const props = withDefaults(defineProps<Props>(), {
  likes: 0,
  isPublished: false
})
</script>
```

### 创建自定义组合式函数

组合式函数约定以"use"开头，返回需要暴露的内容：

```javascript
// useCounter.js
import { ref, computed } from 'vue'

export function useCounter(initialValue = 0) {
  // 状态
  const count = ref(initialValue)

  // 计算属性
  const doubleCount = computed(() => count.value * 2)

  // 方法
  function increment() {
    count.value++
  }

  function decrement() {
    count.value--
  }

  function reset() {
    count.value = initialValue
  }

  // 返回需要暴露的内容
  return {
    count,
    doubleCount,
    increment,
    decrement,
    reset
  }
}
```

在组件中使用：

```vue
<script setup>
import { useCounter } from './composables/useCounter'

// 使用组合式函数
const { count, doubleCount, increment, decrement, reset } = useCounter(10)
</script>

<template>
  <div>
    <p>Count: {{ count }}</p>
    <p>Double: {{ doubleCount }}</p>
    <button @click="increment">+</button>
    <button @click="decrement">-</button>
    <button @click="reset">Reset</button>
  </div>
</template>
```

### 实用组合式函数示例

**1. 封装API请求逻辑**

```javascript
// useApi.js
import { ref } from 'vue'

export function useApi(url) {
  const data = ref(null)
  const error = ref(null)
  const loading = ref(false)

  async function fetchData() {
    loading.value = true
    error.value = null

    try {
      const response = await fetch(url)
      data.value = await response.json()
    } catch (err) {
      error.value = err.message || '请求失败'
    } finally {
      loading.value = false
    }
  }

  return { data, error, loading, fetchData }
}
```

使用：

```vue
<script setup>
import { onMounted } from 'vue'
import { useApi } from './composables/useApi'

const { data, error, loading, fetchData } = useApi('https://api.example.com/data')

onMounted(fetchData)
</script>

### Provide/Inject：跨组件数据传递

Composition API提供了`provide`和`inject`函数，用于实现跨层级组件通信：

```javascript
// 父组件
import { provide, ref } from 'vue'

export default {
  setup() {
    const theme = ref('light')

    function toggleTheme() {
      theme.value = theme.value === 'light' ? 'dark' : 'light'
    }

    // 提供值给后代组件
    provide('theme', theme)
    provide('toggleTheme', toggleTheme)

    return { theme, toggleTheme }
  }
}

// 后代组件（可以是任意深度）
import { inject } from 'vue'

export default {
  setup() {
    // 注入祖先组件提供的值
    const theme = inject('theme')
    const toggleTheme = inject('toggleTheme')

    return { theme, toggleTheme }
  }
}
```

在`<script setup>`中使用：

```vue

<script setup>
import { provide, ref } from 'vue'

const theme = ref('light')

function toggleTheme() {
  theme.value = theme.value === 'light' ? 'dark' : 'light'
}

provide('theme', theme)
provide('toggleTheme', toggleTheme)
</script>

<script setup>
import { inject } from 'vue'

const theme = inject('theme')
const toggleTheme = inject('toggleTheme')
</script>

<template>
  <div :class="theme">
    <button @click="toggleTheme">切换主题</button>
  </div>
</template>
```

### 结合Pinia使用：应用级状态管理

Pinia是Vue官方推荐的状态管理库，它与Composition API结合得非常好：

```javascript
// store/counter.js
import { defineStore } from 'pinia'
import { ref, computed } from 'vue'

export const useCounterStore = defineStore('counter', () => {
  // 状态
  const count = ref(0)

  // 计算属性
  const doubleCount = computed(() => count.value * 2)

  // 方法
  function increment() {
    count.value++
  }

  return { count, doubleCount, increment }
})
```

在组件中使用：

```vue
<script setup>
import { useCounterStore } from '@/store/counter'
import { storeToRefs } from 'pinia'

// 使用store
const counterStore = useCounterStore()

// 解构store（使用storeToRefs保持响应性）
const { count, doubleCount } = storeToRefs(counterStore)
// 方法可以直接解构
const { increment } = counterStore
</script>

<template>
  <div>
    <p>Count: {{ count }}</p>
    <p>Double: {{ doubleCount }}</p>
    <button @click="increment">增加</button>
  </div>
</template>
```

### 代码组织方式：清晰的功能分组

按照功能逻辑组织代码，让相关的代码放在一起：

```vue
<script setup>
import { ref, computed, onMounted } from 'vue'
import { useApi } from './composables/useApi'

// 用户相关功能
const username = ref('')
const isAdmin = ref(false)

function login() {
  // 登录逻辑
