  // 登出逻辑
}

// 文章相关功能
const { data: articles, loading: articlesLoading, fetchData: fetchArticles } = useApi('/api/articles')

const filteredArticles = computed(() => {
  if (!articles.value) return []
  return articles.value.filter(article => /* 过滤逻辑 */)
