### 基本操作
```javascript
// 打开数据库
const request = indexedDB.open('MyDatabase', 1);

// 创建对象仓库
request.onupgradeneeded = function(event) {
  const db = event.target.result;
  const store = db.createObjectStore('users', { keyPath: 'id' });
  store.createIndex('name', 'name', { unique: false });
};

// 添加数据
request.onsuccess = function(event) {
  const db = event.target.result;
  const transaction = db.transaction(['users'], 'readwrite');
  const store = transaction.objectStore('users');
  store.add({ id: 1, name: '张三', email: 'zhangsan@example.com' });
};

// 查询数据
function getUser(id) {
  const db = request.result;
  const transaction = db.transaction(['users']);
  const store = transaction.objectStore('users');
  return store.get(id);
}
```

## 常见错误与注意事项

1. **存储字符串以外的数据类型**
```javascript
// 错误做法
localStorage.setItem('user', { name: '李四', age: 25 });
console.log(localStorage.getItem('user')); // 输出: "[object Object]"

// 正确做法
localStorage.setItem('user', JSON.stringify({ name: '李四', age: 25 }));
const user = JSON.parse(localStorage.getItem('user'));
console.log(user); // 输出: {name: "李四", age: 25}
```

2. **没有做错误处理**
```javascript
// 应该添加错误处理
try {
  localStorage.setItem('bigData', bigDataString);
} catch (e) {
  console.error('存储失败，可能超出了存储限制', e);
  // 这里可以采取备选方案，如清除一些不必要的数据
}
```

3. **依赖存储机制而不检查可用性**
```javascript
// 总是检查功能是否可用
function isLocalStorageAvailable() {
  try {
    const test = '__test__';
    localStorage.setItem(test, test);
    localStorage.removeItem(test);
    return true;
  } catch (e) {
    return false;
  }
}

if (isLocalStorageAvailable()) {
  // 使用 localStorage
} else {
  // 使用备选方案
}
```

#### 1. transition-property：指定哪些属性将发生变化

```css
.element {
  /* 所有可动画属性都会过渡 */
  transition-property: all;

  /* 只有宽度和背景色会过渡 */
  transition-property: width, background-color;

  /* 没有属性会过渡 */
  transition-property: none;
}
```

并非所有CSS属性都支持过渡。通常，具有中间值的属性（如颜色、尺寸、位置等）可以过渡，而离散属性（如`display`）则不能。

#### 2. transition-duration：指定过渡持续时间

```css
.element {
  /* 过渡持续0.5秒 */
  transition-duration: 0.5s;

  /* 也可以使用毫秒 */
  transition-duration: 500ms;

  /* 为不同属性指定不同的持续时间 */
  transition-property: width, height, color;
  transition-duration: 0.5s, 1s, 0.3s;
}
```

#### 3. transition-timing-function：指定过渡的速度曲线

```css
.element {
  /* 标准速度曲线 */
  transition-timing-function: ease; /* 默认值，慢开始，快中间，慢结束 */
  transition-timing-function: linear; /* 匀速 */
  transition-timing-function: ease-in; /* 慢开始，快结束 */
  transition-timing-function: ease-out; /* 快开始，慢结束 */
  transition-timing-function: ease-in-out; /* 慢开始，慢结束 */

  /* 使用贝塞尔曲线自定义速度曲线 */
  transition-timing-function: cubic-bezier(0.42, 0, 0.58, 1);

  /* 阶跃函数 */
  transition-timing-function: steps(4, end);
}
```

#### 4. transition-delay：指定过渡延迟开始的时间

```css
.element {
  /* 过渡延迟0.2秒开始 */
  transition-delay: 0.2s;

  /* 为不同属性指定不同的延迟 */
  transition-property: width, height;
  transition-delay: 0s, 0.5s;
}
```

#### 5. transition：简写属性

```css
.element {
  /* 所有属性过渡，持续0.3秒，线性变化，无延迟 */
  transition: all 0.3s linear 0s;

  /* 多个过渡效果，用逗号分隔 */
  transition: width 0.5s ease-out, height 1s ease-in 0.2s;
}
```

简写属性的顺序是：属性 持续时间 速度曲线 延迟时间，其中只有持续时间是必需的。

